# Consensus in Code: A Raft Core for Kestrel

The previous sections described the protocol. This one implements its core in Go so you can see how the invariants reduce to a few functions. The code is a Raft-style leader election and log replication core, with a deterministic in-memory cluster harness for Kestrel's 5 nodes (A1, A2 in region A; B1, B2 in region B; C1 in region C). It is a teaching implementation. It omits persistence, snapshots, and membership changes, and it does not run Paxos or Zab. I have not compiled or executed this code in this session, so treat it as a reading aid until you run `go test` against it. It targets Go 1.21 or later for the built-in `min`.

## The Protocol Core

This file contains the state machine for a single node. Everything that touches safety lives here.

```go
// raft.go
package kestrel

import "math/rand"

type Role int

const (
	Follower Role = iota
	Candidate
	Leader
)

const (
	electionMinTicks = 10
	heartbeatTicks   = 3
)

type MsgKind int

const (
	MsgRequestVote MsgKind = iota
	MsgVoteResp
	MsgAppend
	MsgAppendResp
)

type Entry struct {
	Term  uint64
	Index uint64
	Cmd   string
}

type Message struct {
	Kind         MsgKind
	From, To     string
	Term         uint64
	LastLogIndex uint64
	LastLogTerm  uint64
	PrevIndex    uint64
	PrevTerm     uint64
	Entries      []Entry
	LeaderCommit uint64
	Granted      bool
	Success      bool
	MatchIndex   uint64
}

type Node struct {
	ID    string
	Peers []string
	rng   *rand.Rand

	currentTerm uint64
	votedFor    string
	log         []Entry // log[0] is a sentinel so real indexes start at 1
	commitIndex uint64
	lastApplied uint64
	role        Role
	leaderID    string

	votes      map[string]bool
	nextIndex  map[string]uint64
	matchIndex map[string]uint64

	electionElapsed  int
	electionTimeout  int
	heartbeatElapsed int

	Applied []Entry // committed entries in order, for the state machine
	out     []Message
}

func New(id string, peers []string, rng *rand.Rand) *Node {
	n := &Node{ID: id, Peers: peers, rng: rng, log: []Entry{{}}}
	n.resetElectionTimeout()
	return n
}

func (n *Node) lastIndex() uint64      { return uint64(len(n.log) - 1) }
func (n *Node) termAt(i uint64) uint64 { return n.log[i].Term }
func (n *Node) quorum() int            { return (len(n.Peers)+1)/2 + 1 }

func (n *Node) resetElectionTimeout() {
	n.electionElapsed = 0
	n.electionTimeout = electionMinTicks + n.rng.Intn(electionMinTicks)
}

// observeTerm enforces the fencing rule: any higher term demotes this node.
func (n *Node) observeTerm(term uint64) {
	if term <= n.currentTerm {
		return
	}
	n.currentTerm = term
	n.votedFor = ""
	n.role = Follower
	n.leaderID = ""
}

// Tick advances logical time by one unit. Followers and candidates count
// toward an election; leaders emit heartbeats.
func (n *Node) Tick() {
	if n.role == Leader {
		n.heartbeatElapsed++
		if n.heartbeatElapsed >= heartbeatTicks {
			n.heartbeatElapsed = 0
			n.broadcastAppend()
		}
		return
	}
	n.electionElapsed++
	if n.electionElapsed >= n.electionTimeout {
		n.startElection()
	}
}

func (n *Node) startElection() {
	n.role = Candidate
	n.currentTerm++
	n.votedFor = n.ID
	n.votes = map[string]bool{n.ID: true}
	n.leaderID = ""
	n.resetElectionTimeout()
	for _, p := range n.Peers {
		n.send(Message{
			Kind:         MsgRequestVote,
			To:           p,
			Term:         n.currentTerm,
			LastLogIndex: n.lastIndex(),
			LastLogTerm:  n.termAt(n.lastIndex()),
		})
	}
}

// Step processes one inbound message. Term observation happens first, so
// every handler sees a consistent view of currentTerm.
func (n *Node) Step(m Message) {
	n.observeTerm(m.Term)
	switch m.Kind {
	case MsgRequestVote:
		n.handleRequestVote(m)
	case MsgVoteResp:
		n.handleVoteResp(m)
	case MsgAppend:
		n.handleAppend(m)
	case MsgAppendResp:
		n.handleAppendResp(m)
	}
}

// upToDate implements the election restriction: a voter grants only to a
// candidate whose log is at least as complete as its own.
func (n *Node) upToDate(lastTerm, lastIndex uint64) bool {
	myTerm := n.termAt(n.lastIndex())
	if lastTerm != myTerm {
		return lastTerm > myTerm
	}
	return lastIndex >= n.lastIndex()
}

func (n *Node) handleRequestVote(m Message) {
	grant := m.Term >= n.currentTerm &&
		(n.votedFor == "" || n.votedFor == m.From) &&
		n.upToDate(m.LastLogTerm, m.LastLogIndex)
	if grant {
		n.votedFor = m.From
		n.resetElectionTimeout()
	}
	n.send(Message{Kind: MsgVoteResp, To: m.From, Term: n.currentTerm, Granted: grant})
}

func (n *Node) handleVoteResp(m Message) {
	if n.role != Candidate || m.Term != n.currentTerm || !m.Granted {
		return
	}
	n.votes[m.From] = true
	if len(n.votes) >= n.quorum() {
		n.becomeLeader()
	}
}

func (n *Node) becomeLeader() {
	n.role = Leader
	n.leaderID = n.ID
	n.nextIndex = map[string]uint64{}
	n.matchIndex = map[string]uint64{}
	for _, p := range n.Peers {
		n.nextIndex[p] = n.lastIndex() + 1
	}
	// Term-start no-op. A leader may not count older entries toward a commit
	// until an entry from its own term is on a quorum (Raft section 5.4.2).
	n.log = append(n.log, Entry{Term: n.currentTerm, Index: n.lastIndex() + 1, Cmd: "noop"})
	n.broadcastAppend()
}

// Propose appends a client command on the leader. Followers refuse.
func (n *Node) Propose(cmd string) (uint64, bool) {
	if n.role != Leader {
		return 0, false
	}
	idx := n.lastIndex() + 1
	n.log = append(n.log, Entry{Term: n.currentTerm, Index: idx, Cmd: cmd})
	n.broadcastAppend()
	return idx, true
}

func (n *Node) broadcastAppend() {
	for _, p := range n.Peers {
		n.sendAppend(p)
	}
}

func (n *Node) sendAppend(to string) {
	next := n.nextIndex[to]
	prev := next - 1
	var entries []Entry
	if n.lastIndex() >= next {
		entries = append([]Entry(nil), n.log[next:]...)
	}
	n.send(Message{
		Kind:         MsgAppend,
		To:           to,
		Term:         n.currentTerm,
		PrevIndex:    prev,
		PrevTerm:     n.termAt(prev),
		Entries:      entries,
		LeaderCommit: n.commitIndex,
	})
}

func (n *Node) handleAppend(m Message) {
	fail := Message{Kind: MsgAppendResp, To: m.From, Term: n.currentTerm, Success: false}
	if m.Term < n.currentTerm {
		n.send(fail)
		return
	}
	n.role = Follower
	n.leaderID = m.From
	n.resetElectionTimeout()

	// Log matching: the entry before the new ones must agree in index and term.
	if m.PrevIndex > n.lastIndex() || n.termAt(m.PrevIndex) != m.PrevTerm {
		n.send(fail)
		return
	}
	for i, e := range m.Entries {
		idx := m.PrevIndex + 1 + uint64(i)
		if idx <= n.lastIndex() {
			if n.termAt(idx) == e.Term {
				continue
			}
			n.log = n.log[:idx] // conflict: discard the divergent suffix
		}
		n.log = append(n.log, e)
	}

	lastNew := m.PrevIndex + uint64(len(m.Entries))
	if m.LeaderCommit > n.commitIndex {
		n.commitIndex = min(m.LeaderCommit, lastNew)
	}
	n.applyCommitted()
	n.send(Message{
		Kind:       MsgAppendResp,
		To:         m.From,
		Term:       n.currentTerm,
		Success:    true,
		MatchIndex: lastNew,
	})
}

func (n *Node) handleAppendResp(m Message) {
	if n.role != Leader || m.Term != n.currentTerm {
		return
	}
	if !m.Success {
		if n.nextIndex[m.From] > 1 {
			n.nextIndex[m.From]--
		}
		n.sendAppend(m.From)
		return
	}
	if m.MatchIndex > n.matchIndex[m.From] {
		n.matchIndex[m.From] = m.MatchIndex
		n.nextIndex[m.From] = m.MatchIndex + 1
	}
	n.advanceCommit()
}

// advanceCommit moves the commit index to the highest index stored on a
// quorum, but only for entries from the current term.
func (n *Node) advanceCommit() {
	for idx := n.lastIndex(); idx > n.commitIndex; idx-- {
		if n.termAt(idx) != n.currentTerm {
			break // terms are nondecreasing, so no lower index qualifies
		}
		count := 1 // the leader itself
		for _, p := range n.Peers {
			if n.matchIndex[p] >= idx {
				count++
			}
		}
		if count >= n.quorum() {
			n.commitIndex = idx
			n.applyCommitted()
			return
		}
	}
}

func (n *Node) applyCommitted() {
	for n.lastApplied < n.commitIndex {
		n.lastApplied++
		n.Applied = append(n.Applied, n.log[n.lastApplied])
	}
}

func (n *Node) send(m Message) {
	m.From = n.ID
	n.out = append(n.out, m)
}

// Drain returns and clears the outbound message queue.
func (n *Node) Drain() []Message {
	out := n.out
	n.out = nil
	return out
}
```

## The Deterministic Harness

The harness makes the network explicit. Messages are delivered in a fixed order, and partitions are a set of blocked directed pairs. This is what lets a failure story become a repeatable test.

```go
// cluster.go
package kestrel

import "math/rand"

var regionA = []string{"A1", "A2"}

type Cluster struct {
	IDs     []string
	Nodes   map[string]*Node
	blocked map[[2]string]bool
	queue   []Message
}

func NewKestrelCluster(seed int64) *Cluster {
	ids := []string{"A1", "A2", "B1", "B2", "C1"}
	rng := rand.New(rand.NewSource(seed))
	c := &Cluster{IDs: ids, Nodes: map[string]*Node{}, blocked: map[[2]string]bool{}}
	for _, id := range ids {
		var peers []string
		for _, p := range ids {
			if p != id {
				peers = append(peers, p)
			}
		}
		c.Nodes[id] = New(id, peers, rng)
	}
	return c
}

// Step runs one round: tick every node, collect outbound messages, then
// deliver those not blocked by the current partition.
func (c *Cluster) Step() {
	for _, id := range c.IDs {
		c.Nodes[id].Tick()
	}
	for _, id := range c.IDs {
		c.queue = append(c.queue, c.Nodes[id].Drain()...)
	}
	pending := c.queue
	c.queue = nil
	for _, m := range pending {
		if c.blocked[[2]string{m.From, m.To}] {
			continue
		}
		c.Nodes[m.To].Step(m)
	}
}

func (c *Cluster) Run(rounds int) {
	for i := 0; i < rounds; i++ {
		c.Step()
	}
}

// RunUntilLeader steps until one of the listed nodes is leader.
func (c *Cluster) RunUntilLeader(among []string, maxRounds int) (string, bool) {
	for i := 0; i < maxRounds; i++ {
		c.Step()
		for _, id := range among {
			if c.Nodes[id].role == Leader {
				return id, true
			}
		}
	}
	return "", false
}

// Isolate blocks all traffic between group and the rest of the cluster.
func (c *Cluster) Isolate(group []string) {
	in := map[string]bool{}
	for _, g := range group {
		in[g] = true
	}
	for _, a := range c.IDs {
		for _, b := range c.IDs {
			if in[a] != in[b] {
				c.blocked[[2]string{a, b}] = true
			}
		}
	}
}

func (c *Cluster) Heal() {
	c.blocked = map[[2]string]bool{}
}
```

## The Failover Test

The test reproduces the regional failure from the walkthrough. It commits a debit, isolates region A, requires the majority side to elect a leader, then heals the partition and checks that every node's committed history is a prefix of the same sequence.

```go
// failover_test.go
package kestrel

import "testing"

const debitCmd = "debit acct-42 500"

func countCmd(log []Entry, cmd string) int {
	n := 0
	for _, e := range log {
		if e.Cmd == cmd {
			n++
		}
	}
	return n
}

// sameUpTo reports whether the shorter of a and b is a prefix of the other.
func sameUpTo(a, b []Entry) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i].Term != b[i].Term || a[i].Cmd != b[i].Cmd {
			return false
		}
	}
	return true
}

func TestRegionFailoverPreservesCommittedDebit(t *testing.T) {
	c := NewKestrelCluster(42)

	leaderID, ok := c.RunUntilLeader(c.IDs, 500)
	if !ok {
		t.Fatal("no leader elected")
	}
	idx, ok := c.Nodes[leaderID].Propose(debitCmd)
	if !ok {
		t.Fatal("leader refused proposal")
	}
	c.Run(30)
	if c.Nodes[leaderID].commitIndex < idx {
		t.Fatalf("debit not committed at index %d", idx)
	}

	c.Isolate(regionA)
	majority := []string{"B1", "B2", "C1"}
	newLeader, ok := c.RunUntilLeader(majority, 1000)
	if !ok {
		t.Fatal("no leader elected on majority side")
	}
	c.Run(30)

	for _, id := range majority {
		if got := countCmd(c.Nodes[id].Applied, debitCmd); got != 1 {
			t.Errorf("%s applied debit %d times, want 1", id, got)
		}
	}

	c.Heal()
	c.Run(60)
	ref := c.Nodes[newLeader].Applied
	for _, id := range c.IDs {
		if !sameUpTo(c.Nodes[id].Applied, ref) {
			t.Errorf("%s committed history diverges from %s", id, newLeader)
		}
	}
}
```

## How the Code Maps to the Protocol

**Terms are fences.** `observeTerm` runs before every message handler. A node that sees a higher term steps down and clears its vote. A stale leader that wakes up behind a partition is demoted the moment it hears from the new majority, and its old messages are rejected by the `m.Term < n.currentTerm` checks.

**Votes are restricted.** `upToDate` is the election restriction from the walkthrough. B1 won the election in the example because its log ended at term 7, index 1041, which beat B2's index 1040. Quorum intersection guarantees that any winning candidate has every entry that was committed. Here it is a comparison, not a theorem.

**Log matching is enforced on followers.** `handleAppend` rejects any batch whose `PrevIndex` and `PrevTerm` don't match the local log. On mismatch, the leader decrements `nextIndex` and retries until the logs agree. Only then does a follower truncate a conflicting suffix. Truncation happens only on a term conflict, so a follower with extra matching entries keeps them.

**The commit rule carries the safety argument.** `advanceCommit` counts matches only for entries from the current term, and it stops scanning downward once it reaches an older term. The term-start no-op in `becomeLeader` is what makes this rule useful: after a failover, the new leader commits its no-op, which commits the inherited debit with it. Without the no-op, the leader would be stuck, because it cannot count older entries on their own.

**Apply is separate from commit.** `Applied` is the output the ledger's state machine consumes. Deduplication by idempotency key, shown earlier, belongs in that consumer. The core only guarantees that every node applies the same sequence.

**What is missing for production.** `currentTerm`, `votedFor`, and `log` must be written to stable storage and synced before any response that depends on them leaves the node. The harness assumes that happens. Section 5 explained what happens when it does not. Snapshots, membership change, and linearizable reads are also absent, and each is a source of the failure stories from the previous section.

**Paxos and Zab would look different.** Paxos would replace the single log with independent slots, each decided by `prepare` and `accept` rounds that must re-propose the highest previously accepted value. Zab would split recovery into discovery and synchronization phases before the leader broadcasts. The safety argument would be the same, and the testing approach carries over directly.

Key takeaway: The entire safety story of Raft fits in a few functions, term fencing in `observeTerm`, the election restriction in `upToDate`, log matching in `handleAppend`, and the current-term commit rule in `advanceCommit`, and the deterministic harness lets you check Kestrel's regional failover as a repeatable test instead of an incident you hope never happens.

# A Consistency Simulator for Kestrel: Levels, Tokens, and Invariant Tests

The earlier sections described CAP and the consistency spectrum in prose and in a routing sketch. This section builds a small, runnable model of the behavior: a 5-node ledger with a fixed leader, partitions that isolate nodes, three read levels, client session tokens, and a randomized test that checks the guarantees each level promises. The model is not a consensus protocol. Commits are immediate and the leader never fails, so it isolates the question the earlier sections care about: what does each read return, and when is it refused? The code is in Go, split into two files, and I have not compiled or run it in this session.

## The Store: `store.go`

```go
// store.go
package consistency

import "errors"

type Level int

const (
	Linearizable Level = iota
	Session
	Eventual
)

var (
	ErrUnavailable = errors.New("unavailable: quorum not reachable")
	ErrNotCaughtUp = errors.New("node has not applied the session index")
	ErrBadLevel    = errors.New("unknown read level")
)

var kestrelIDs = []string{"A1", "A2", "B1", "B2", "C1"}

// Op is one ledger entry. Its commit index is its position plus one.
type Op struct {
	Key   string
	Delta int64
}

type Node struct {
	ID      string
	state   map[string]int64
	applied uint64 // count of log entries applied, equal to the highest applied index
}

func (n *Node) applyUpTo(log []Op, index uint64) {
	for n.applied < index {
		op := log[n.applied]
		n.state[op.Key] += op.Delta
		n.applied++
	}
}

// Token is a client's session state: the highest commit index it has observed.
type Token struct {
	MinIndex uint64
}

func (t *Token) Observe(idx uint64) {
	if idx > t.MinIndex {
		t.MinIndex = idx
	}
}

type Result struct {
	Value int64
	Index uint64 // the commit index the value reflects
}

type Cluster struct {
	IDs      []string
	nodes    map[string]*Node
	leader   string
	log      []Op
	isolated map[string]bool
}

func NewCluster(ids []string, leader string) *Cluster {
	c := &Cluster{
		IDs:      ids,
		nodes:    map[string]*Node{},
		leader:   leader,
		isolated: map[string]bool{},
	}
	for _, id := range ids {
		c.nodes[id] = &Node{ID: id, state: map[string]int64{}}
	}
	return c
}

func (c *Cluster) quorum() int { return len(c.IDs)/2 + 1 }

// reachable models a single partition: the isolated set versus everyone else.
func (c *Cluster) reachable(a, b string) bool {
	return c.isolated[a] == c.isolated[b]
}

func (c *Cluster) reachableCount(from string) int {
	n := 0
	for _, id := range c.IDs {
		if c.reachable(from, id) {
			n++
		}
	}
	return n
}

func (c *Cluster) CommitIndex() uint64 { return uint64(len(c.log)) }

func (c *Cluster) Isolate(id string) { c.isolated[id] = true }

func (c *Cluster) Heal() {
	c.isolated = map[string]bool{}
	c.syncReachable()
}

// syncReachable applies the committed log to every node the leader can reach.
// Isolated nodes keep their old applied index, which is the source of staleness.
func (c *Cluster) syncReachable() {
	for _, id := range c.IDs {
		if c.reachable(c.leader, id) {
			c.nodes[id].applyUpTo(c.log, c.CommitIndex())
		}
	}
}

// Write commits only if the leader can reach a quorum, and returns the
// commit index so the caller can record it in a session token.
func (c *Cluster) Write(key string, delta int64) (uint64, error) {
	if c.reachableCount(c.leader) < c.quorum() {
		return 0, ErrUnavailable
	}
	c.log = append(c.log, Op{Key: key, Delta: delta})
	c.syncReachable()
	return c.CommitIndex(), nil
}

// Read dispatches on the requested level. Every successful read advances the
// client's token, so later session reads cannot move backward.
func (c *Cluster) Read(at, key string, level Level, tok *Token) (Result, error) {
	if tok == nil {
		tok = &Token{}
	}
	res, err := c.read(at, key, level, tok)
	if err == nil {
		tok.Observe(res.Index)
	}
	return res, err
}

func (c *Cluster) read(at, key string, level Level, tok *Token) (Result, error) {
	n := c.nodes[at]
	switch level {
	case Linearizable:
		// Requires a quorum on the caller's side that includes the leader.
		// The answer is the committed state, which the leader holds in full.
		if !c.reachable(at, c.leader) || c.reachableCount(at) < c.quorum() {
			return Result{}, ErrUnavailable
		}
		return Result{Value: c.nodes[c.leader].state[key], Index: c.CommitIndex()}, nil

	case Session:
		// Refuse rather than return a value older than the client has seen.
		if n.applied < tok.MinIndex {
			return Result{}, ErrNotCaughtUp
		}
		return Result{Value: n.state[key], Index: n.applied}, nil

	case Eventual:
		// Always answers from local state, however far behind it is.
		return Result{Value: n.state[key], Index: n.applied}, nil
	}
	return Result{}, ErrBadLevel
}

// ValueAt replays the log to give the value a key should have at an index.
// It is the reference model that every read is checked against.
func (c *Cluster) ValueAt(key string, idx uint64) int64 {
	var v int64
	for _, op := range c.log[:idx] {
		if op.Key == key {
			v += op.Delta
		}
	}
	return v
}
```

## Reading the Model

The file has five pieces, and each corresponds to a concept from the earlier sections.

**Partitions are a set.** `isolated` names the nodes on the minority side. Two nodes can communicate exactly when both are inside or both are outside that set. This is a single-partition model, which is enough to exhibit CAP's trade-off and keeps the reachability logic readable.

**Writes need a quorum from the leader.** `Write` refuses unless the leader can reach three of five nodes. A write that succeeds has a commit index, and that index is what a client records. Writes that fail are never observed, which matters for the session checks below.

**Each read level has a distinct refusal condition.** This is the heart of the model.

- `Linearizable` answers only when the caller can reach the leader and a quorum on its side. It returns the committed state and the current commit index. On the minority side it returns `ErrUnavailable`, which is the CP choice: no answer rather than a possibly wrong one.
- `Session` answers only from a node that has applied at least the client's token index. Otherwise it returns `ErrNotCaughtUp`. This is the cheapest guarantee that still prevents a customer's own payment from disappearing.
- `Eventual` always answers. It is the AP choice, and it can return a state that is arbitrarily far behind the commit index.

**Tokens carry history between reads.** `Read` advances the client's token to the index of every successful result, regardless of level. That means a client that has seen index 2 through an eventual read cannot later be served index 1 through a session read. Monotonic reads across levels fall out of this one line.

**`ValueAt` is the oracle.** It recomputes what a key should be at any index from the log alone. That gives the tests a reference that does not depend on any node's state. It also supports one useful property that does not depend on how stale a read is: every read, at every level, must return a prefix state, meaning the value at some index that was actually committed. An eventual read can be old, but it cannot be invented.

## The Scenario Test and the Property Test

The second file has two kinds of test. The first reproduces the incident from the previous section, step by step, with explicit expected outcomes. The second drives random interleavings of writes, partitions, heals, and reads, and checks the invariants after every successful read.

```go
// consistency_test.go
package consistency

import (
	"math/rand"
	"testing"
)

func must(t *testing.T, err error) {
	t.Helper()
	if err != nil {
		t.Fatal(err)
	}
}

// TestPartitionScenario reproduces the incident from the worked example.
func TestPartitionScenario(t *testing.T) {
	c := NewCluster(kestrelIDs, "A1")

	idx, err := c.Write("acct-42", 1000) // opening balance
	must(t, err)
	var mobile Token
	mobile.Observe(idx)

	c.Isolate("C1")
	idx, err = c.Write("acct-42", -500) // debit on the majority side
	must(t, err)
	mobile.Observe(idx)

	if _, err := c.Read("C1", "acct-42", Linearizable, nil); err != ErrUnavailable {
		t.Fatalf("linearizable read on minority: got %v, want ErrUnavailable", err)
	}
	if _, err := c.Read("C1", "acct-42", Session, &mobile); err != ErrNotCaughtUp {
		t.Fatalf("session read on minority: got %v, want ErrNotCaughtUp", err)
	}
	res, err := c.Read("C1", "acct-42", Eventual, nil)
	if err != nil || res.Value != 1000 || res.Index != 1 {
		t.Fatalf("eventual read on minority: got %+v, %v; want stale 1000 at index 1", res, err)
	}
	res, err = c.Read("B1", "acct-42", Linearizable, nil)
	if err != nil || res.Value != 500 || res.Index != 2 {
		t.Fatalf("linearizable read on majority: got %+v, %v; want 500 at index 2", res, err)
	}

	c.Heal()
	res, err = c.Read("C1", "acct-42", Session, &mobile)
	if err != nil || res.Value != 500 || res.Index != 2 {
		t.Fatalf("session read after heal: got %+v, %v; want 500 at index 2", res, err)
	}
}

// TestRandomizedGuarantees runs many random histories and checks invariants.
func TestRandomizedGuarantees(t *testing.T) {
	var stale, eventual int
	for seed := int64(1); seed <= 200; seed++ {
		s, e := runRandom(t, seed)
		stale += s
		eventual += e
	}
	t.Logf("eventual reads: %d of %d returned a stale value", stale, eventual)
}

func runRandom(t *testing.T, seed int64) (stale, eventual int) {
	t.Helper()
	rng := rand.New(rand.NewSource(seed))
	c := NewCluster(kestrelIDs, "A1")
	tokens := make([]Token, 2) // two clients, each with its own session

	for step := 0; step < 300; step++ {
		client := rng.Intn(len(tokens))
		switch action := rng.Intn(10); {
		case action == 0:
			c.Heal()
		case action == 1:
			c.Isolate(kestrelIDs[rng.Intn(len(kestrelIDs))])
		case action < 4:
			idx, err := c.Write("acct-42", int64(rng.Intn(200)-100))
			if err == nil {
				tokens[client].Observe(idx)
			}
		default:
			at := kestrelIDs[rng.Intn(len(kestrelIDs))]
			level := Level(rng.Intn(3))
			before := tokens[client].MinIndex
			res, err := c.Read(at, "acct-42", level, &tokens[client])
			if err != nil {
				continue
			}
			if res.Index > c.CommitIndex() {
				t.Fatalf("seed %d step %d: read index %d beyond commit %d",
					seed, step, res.Index, c.CommitIndex())
			}
			if want := c.ValueAt("acct-42", res.Index); res.Value != want {
				t.Fatalf("seed %d step %d: %v read at %s returned %d, want %d at index %d",
					seed, step, level, at, res.Value, want, res.Index)
			}
			if level != Eventual && res.Index < before {
				t.Fatalf("seed %d step %d: %v read went backward: index %d < %d",
					seed, step, level, res.Index, before)
			}
			if level == Linearizable && res.Index != c.CommitIndex() {
				t.Fatalf("seed %d step %d: linearizable read at index %d, commit is %d",
					seed, step, res.Index, c.CommitIndex())
			}
			if level == Eventual {
				eventual++
				if res.Index < c.CommitIndex() {
					stale++
				}
			}
		}
	}
	return stale, eventual
}
```

The scenario test asserts the four decisions from the worked example. The minority side refuses linearizable reads, refuses session reads that would move the customer backward, serves a stale eventual read labeled by its index, and recovers once the partition heals. Each assertion encodes an expected outcome, so a regression changes a specific line, not a vague behavior.

The randomized test checks four invariants on every successful read. The result must not reflect an index beyond the commit. It must equal the reference value at its own index, which is the prefix property. Session and linearizable reads must not move backward for the client that issued them. Linearizable reads must reflect the latest commit. It also counts how many eventual reads were stale, so the test output shows the availability trade-off as a number rather than an assertion.

## What the Tests Catch

A test is only useful if it fails when the design is wrong. Consider a plausible regression: someone "simplifies" the linearizable path to read the local node's state, on the reasoning that the leader and the local node usually agree.

```go
case Linearizable:
    return Result{Value: n.state[key], Index: n.applied}, nil // regression
```

The scenario test fails immediately at the first assertion, because C1 now returns a value instead of `ErrUnavailable`. The randomized test would also fail, on the linearizable check `res.Index != c.CommitIndex()`, as soon as a read on an isolated node reached it. That is the point of keeping both kinds of test. The scenario test documents intent, and the randomized test finds the cases nobody wrote down.

The other likely regression is the token logic. If `Read` stopped observing the index for eventual reads, the monotonic check across levels would still pass, because eventual reads are excluded from that check. The guarantee is that a client's session reads never go backward, and the test enforces that through session and linearizable reads only, which is correct. If the token were not advanced for session reads, the `before` check would catch it.

## Limits of the Model

The model is deliberately narrow, and its limits are worth stating.

Commits are instantaneous and the leader never changes. A real consensus protocol has elections, log replication delays, and terms, and the failure stories in the earlier sections come from those mechanics. This model does not show what happens during a leader change; it shows what each read level promises and when it refuses. To test the consensus layer itself, use the Raft-style core and harness from the earlier implementation section, and check its histories with the same invariants.

Only one partition shape is modeled, a minority set against the rest. Real topologies include asymmetric links and partial partitions, where A can reach B and B can reach C but A cannot reach C. The reachability function would need to become a full matrix, and the linearizable path would need to check the leader's reachability from the caller's side, which it already does here.

The randomized test checks safety properties only. It does not check liveness, such as whether a session read eventually succeeds after the partition heals. That is a separate test, and it requires modeling time, which this model omits.

The strongest use of this file is as a template. The levels, the token, the reference oracle, and the invariant checks transfer directly to any store that exposes multiple read levels. The reference oracle is the most important part: if you can recompute the expected value at any index from the log, you can check every read without trusting the implementation under test.

Key takeaway: The simulator makes each consistency level a concrete refusal condition, linearizable reads refuse without a quorum, session reads refuse before the client's own writes are visible, and eventual reads always answer with a labeled index, and the randomized oracle checks that every answer is a real committed prefix that never moves a client backward, so a regression that trades a guarantee for convenience fails a test instead of reaching a customer.

# Worked Example: A Regional Failover on a Two-Region Copy Policy

The earlier sections described the mechanisms and their failure modes. This walkthrough applies them to one realistic sequence: declaring a copy policy, running steady state, losing a region mid-flight, promoting a copy, rejoining the failed node, and reconciling the result. The example uses Kestrel, our 5-node, 3-region payments ledger. The code fragments are in Go and are sketches for discussion. I have not compiled them in this session.

## Step 1: Declare the Policy Before Running Anything

Kestrel's ledger uses the following copy policy for the balance log. Each entry must be stored on the leader and on one node in a different region before the client is acknowledged. The declared loss bound is zero for the loss of any single region, because at least two regions hold every acknowledged entry. The policy does not protect against the simultaneous loss of both regions, and that is recorded as an accepted risk.

Nodes are A1 (leader, region A), A2 (region A), B1 and B2 (region B), and C1 (region C). The acknowledgment set is A1 plus B1, which is the nearest node outside region A. Measured p99 lag from A1 to B1 is 8 milliseconds, and the measured round trip is about 6 milliseconds.

```go
type CopyPolicy struct {
    Acks        int
    MaxLossTime time.Duration
}

func (p CopyPolicy) Check(measuredLagP99 time.Duration) error {
    if p.Acks >= 2 && measuredLagP99 > p.MaxLossTime && p.MaxLossTime > 0 {
        return fmt.Errorf("lag %v exceeds declared bound %v", measuredLagP99, p.MaxLossTime)
    }
    return nil
}
```

The check passes for this policy, and the team records the decision: two-region acknowledgment, zero loss for a single-region failure, and a stated accepted risk for a double-region failure.

## Step 2: Steady State

At 13:59:58, the gateway submits a debit of 500 against `acct-42` with idempotency key `pay-7f3c`. A1 appends the entry at index 5031 in term 7, stores it durably, and sends it to B1 and to the other nodes. B1 stores the entry and acknowledges. A1 now holds two stored copies, meets the acknowledgment set, advances its commit index to 5031, applies the debit, and returns a receipt.

The remaining nodes, A2, B2, and C1, receive the entry asynchronously. Their applied positions trail the commit index by a few milliseconds under normal load. The earlier entries 5032 through 5036 follow the same pattern, and each one is acknowledged only after B1 has it.

At 14:00:00, A1 has acknowledged entries through 5036. Entries 5037, 5038, and 5039 are in flight: A1 has stored them durably, has sent them to B1, but has not yet received B1's acknowledgment and has therefore told no client they succeed. B1 holds through 5036.

## Step 3: The Region Fails

At 14:00:01, region A loses power. A1 and A2 go offline. The entries 5037 through 5039 exist only on A1, and no client has been told they committed. The gateway received no receipts for them and will retry them with their original idempotency keys.

The failover controller detects the loss of A1 after its 30-second detection window, which is 14:00:31. It does not promote immediately. It first checks the candidates against the acknowledgment high watermark, which is the highest index that any client has been told is committed, tracked by the controller from the acknowledgments it has issued.

```go
type Candidate struct {
    ID         string
    AppliedIdx uint64
}

func PromoteBest(cands []Candidate, ackHighWater, maxLoss uint64) (Candidate, error) {
    best := cands[0]
    for _, c := range cands[1:] {
        if c.AppliedIdx > best.AppliedIdx {
            best = c
        }
    }
    if ackHighWater > best.AppliedIdx && ackHighWater-best.AppliedIdx > maxLoss {
        return Candidate{}, fmt.Errorf("best candidate %s is %d entries behind the acknowledged watermark, bound is %d",
            best.ID, ackHighWater-best.AppliedIdx, maxLoss)
    }
    return best, nil
}
```

The inputs are B1 at 5036, B2 at 5034, and C1 at 5032. The acknowledgment watermark is 5036. The best candidate is B1, and its gap to the watermark is zero, which is within the declared bound of zero. The controller promotes B1 at 14:00:32 in term 8 and issues a fencing token with that term to every downstream system that accepts ledger output.

## Step 4: Fencing and Client Recovery

Two things must happen before the new leader accepts writes. The external card-network gateway, which receives authorizations from the ledger, is updated to accept only tokens with term 8 or higher. Any request from A1 carrying term 7 is refused, so if region A returns in a partially restored state and A1 tries to send authorizations, the external system rejects them.

The gateway, meanwhile, retries the three in-flight debits with their original idempotency keys. B1, now leader, has no entries for 5037 through 5039 and appends them as new entries at indexes 5037 through 5039 in term 8. Each commit happens only after B1 and one other node store it, and each retry returns a receipt. The idempotency check at apply time ensures that no debit is applied twice if an original attempt had partially reached B1, which in this sequence it had not.

Service is restored at 14:00:40, roughly 39 seconds after the failure. Writes were unavailable for that interval, and the team's stated trade-off was that it is the price of the zero loss bound.

## Step 5: The Old Leader Rejoins

Region A is restored at 14:20:00. A1 starts with term 7 and a log ending at 5039. It receives a heartbeat from B1 in term 8 and steps down, as the term-observation rule requires.

Its entries 5037 through 5039 conflict with the new leader's entries at the same indexes. These conflicting entries were never acknowledged to a client, and their external effect was never produced, because the design requires that external authorizations be sent only after commit. A1 therefore truncates the divergent suffix and adopts B1's history. No compensation is needed. The design rule that external effects follow commit is what makes this safe, and it is the rule that the earlier failover story violated.

Convergence is verified by comparing summaries of each node's log, using a Merkle tree over index ranges. A1's summary matches B1's after 4 minutes of catch-up transfer, and A2, which had been offline with it, converges in the same window. The convergence time is recorded against the target of 10 minutes for this data type.

## Step 6: Reconciliation

Reconciliation is the final check, and it matters because the other checks prove agreement between nodes, not agreement with the outside world. A daily job compares the ledger's committed entries with the settlement file from the card network for the affected window.

```go
func Reconcile(ledger, settled map[string]int64) []string {
    var diffs []string
    for key, amount := range ledger {
        if got, ok := settled[key]; !ok || got != amount {
            diffs = append(diffs, key)
        }
    }
    for key := range settled {
        if _, ok := ledger[key]; !ok {
            diffs = append(diffs, key)
        }
    }
    return diffs
}
```

For the window from 13:59:50 to 14:01:00, the job reports no differences. The three retried debits appear in both the ledger and the settlement file with matching amounts and single entries. The job also confirms that no authorization from term 7 reached the card network after the failover, because the fencing check refused any that arrived.

## The Leaderless Counter in the Same Window

The fraud counters, which are mergeable and run on a leaderless path, followed a different track in the same incident. During the 90 seconds before the promotion, C1 continued to accept increments for merchants whose traffic was routed to it, and the increments were stored as hints for nodes in region A that were unreachable. When region A returned, hints were delivered and the counters merged by taking the per-node maximum. The counters converged within about 3 minutes. The team had set a hint retention limit of six hours, longer than the longest planned maintenance window, which is the lesson from the earlier settlement-report incident applied in advance.

## What the Example Shows

Four things are worth taking from the walkthrough. The loss bound was declared and checked before the failure, so the promotion rule could enforce it rather than discover it. Fencing ensured the old leader could not act on the outside world. The design placed external effects after commit, so truncation of the unacknowledged tail needed no compensation. And every claim, from loss bound to convergence time to reconciliation, was checked by a specific measurement rather than inferred from the absence of errors.

Key takeaway: The worked example shows that a copy strategy is only as sound as its declared bounds and the sequence that enforces them, since a two-region acknowledgment policy with a zero loss bound, a promotion rule that refuses a candidate behind the acknowledged watermark, fencing that refuses stale leaders, external effects gated on commit, and convergence and reconciliation checks together let Kestrel lose an entire region without losing an acknowledged payment.

# A Copy-Strategy Simulator for Kestrel: Acknowledgment, Lag, Promotion, Fencing, and Rejoin

The earlier sections described each strategy in prose and in fragments. This section puts them together in one runnable package: a leader-based ledger with a declared acknowledgment policy, followers that receive entries with per-node lag, promotion that enforces a declared loss bound, epoch fencing on the external side, rejoin with prefix matching, and a leaderless counter for comparison. Time is a tick counter, so every run is repeatable. The code is in Go, split across four files. I have not compiled or run it in this session, so treat the first run as the first real test.

## The Node and the Policy: `copies.go`

```go
// copies.go
// Package copies is a deterministic simulator of copy strategies for the
// Kestrel ledger. Time is a tick counter, so every run is repeatable.
package copies

import "errors"

var (
	ErrLeaderDown = errors.New("leader is down")
	ErrLossBound  = errors.New("promotion would lose more acknowledged entries than the declared bound")
	ErrStale      = errors.New("request carries a stale epoch")
)

// Command is one ledger operation. Nondeterministic values are stamped by
// the leader before the entry is appended, never inside apply.
type Command struct {
	IdemKey string
	Account string
	Amount  int64
	Stamp   int64
}

type Entry struct {
	Epoch uint64
	Cmd   Command
}

// AckPolicy states how many nodes, leader included, must store an entry
// before the client is told yes. Acks == 1 is asynchronous acknowledgment.
type AckPolicy struct {
	Acks int
}

type Node struct {
	ID       string
	down     bool
	epoch    uint64
	log      []Entry // log[i] holds index i+1
	applied  uint64
	balances map[string]int64
	seen     map[string]bool
}

func newNode(id string) *Node {
	return &Node{ID: id, balances: map[string]int64{}, seen: map[string]bool{}}
}

// applyEntry is the deterministic state transition. A repeated idempotency
// key has no further effect, which makes client retries safe.
func (n *Node) applyEntry(e Entry) {
	if n.seen[e.Cmd.IdemKey] {
		return
	}
	n.seen[e.Cmd.IdemKey] = true
	n.balances[e.Cmd.Account] += e.Cmd.Amount
}

// applyTo applies the entries this node holds, up to the commit index.
func (n *Node) applyTo(commit uint64) {
	for n.applied < commit && n.applied < uint64(len(n.log)) {
		n.applyEntry(n.log[n.applied])
		n.applied++
	}
}

// rebuild discards applied state and reapplies the log prefix. A rejoining
// node may have applied entries the cluster later lost, so its state is
// recomputed rather than patched.
func (n *Node) rebuild(commit uint64) {
	n.balances = map[string]int64{}
	n.seen = map[string]bool{}
	n.applied = 0
	n.applyTo(commit)
}

type delivery struct {
	to    string
	at    int64
	epoch uint64
	index uint64
	entry Entry
}

type Cluster struct {
	now      int64
	ids      []string
	nodes    map[string]*Node
	leader   string
	epoch    uint64
	policy   AckPolicy
	delay    map[string]int64 // one-way delay from the leader, in ticks
	inflight []delivery
	commit   uint64            // highest index acknowledged to clients
	stores   map[uint64]map[string]bool
	acked    map[string]uint64 // idempotency key -> index acknowledged
	gateway  *Gateway
}

func NewCluster(ids []string, leader string, policy AckPolicy, delay map[string]int64) *Cluster {
	c := &Cluster{
		ids:     ids,
		nodes:   map[string]*Node{},
		leader:  leader,
		epoch:   1,
		policy:  policy,
		delay:   delay,
		stores:  map[uint64]map[string]bool{},
		acked:   map[string]uint64{},
		gateway: &Gateway{authorized: map[string]int64{}},
	}
	for _, id := range ids {
		c.nodes[id] = newNode(id)
	}
	c.gateway.observe(c.epoch)
	return c
}

func (c *Cluster) Node(id string) *Node  { return c.nodes[id] }
func (c *Cluster) Commit() uint64        { return c.commit }
func (c *Cluster) Epoch() uint64         { return c.epoch }
func (c *Cluster) Gateway() *Gateway     { return c.gateway }

func (c *Cluster) markStored(idx uint64, id string) {
	if c.stores[idx] == nil {
		c.stores[idx] = map[string]bool{}
	}
	c.stores[idx][id] = true
}

// Append takes a command at the leader. The entry is stored there at once;
// followers receive it on later ticks. The client is acknowledged only when
// advance moves the commit index past it.
func (c *Cluster) Append(cmd Command) (uint64, error) {
	ln := c.nodes[c.leader]
	if ln.down {
		return 0, ErrLeaderDown
	}
	cmd.Stamp = c.now // resolved on the leader, before the entry exists
	ln.log = append(ln.log, Entry{Epoch: c.epoch, Cmd: cmd})
	idx := uint64(len(ln.log))
	c.markStored(idx, c.leader)
	c.advance()
	return idx, nil
}

// Tick advances time one unit: the leader queues missing entries, due
// deliveries are stored, and the commit index is recomputed.
func (c *Cluster) Tick() {
	c.now++
	c.pump()
	c.deliver()
	c.advance()
}

func (c *Cluster) Run(ticks int) {
	for i := 0; i < ticks; i++ {
		c.Tick()
	}
}

func (c *Cluster) queued(to string, idx uint64) bool {
	for _, d := range c.inflight {
		if d.to == to && d.index == idx {
			return true
		}
	}
	return false
}

// pump queues, for each reachable follower, every leader entry it lacks and
// that is not already in transit. Entries dropped in transit are refilled here.
func (c *Cluster) pump() {
	ll := c.nodes[c.leader]
	if ll.down {
		return
	}
	for _, id := range c.ids {
		n := c.nodes[id]
		if id == c.leader || n.down {
			continue
		}
		for idx := uint64(len(n.log)) + 1; idx <= uint64(len(ll.log)); idx++ {
			if c.queued(id, idx) {
				continue
			}
			c.inflight = append(c.inflight, delivery{
				to: id, at: c.now + c.delay[id], epoch: c.epoch,
				index: idx, entry: ll.log[idx-1],
			})
		}
	}
}

func (c *Cluster) deliver() {
	kept := c.inflight[:0]
	for _, d := range c.inflight {
		if d.at > c.now {
			kept = append(kept, d)
			continue
		}
		n := c.nodes[d.to]
		// Refuse traffic from a superseded epoch, and entries that do not
		// extend the log contiguously. pump resends the latter.
		if !n.down && d.epoch >= n.epoch && d.index == uint64(len(n.log))+1 {
			n.log = append(n.log, d.entry)
			n.epoch = d.epoch
			c.markStored(d.index, d.to)
		}
	}
	c.inflight = kept
}

// advance commits, in order, each index stored by at least the policy's
// number of nodes. It then applies committed entries on every reachable node.
func (c *Cluster) advance() {
	ll := c.nodes[c.leader]
	for !ll.down && uint64(len(ll.log)) > c.commit && len(c.stores[c.commit+1]) >= c.policy.Acks {
		c.commit++
		key := ll.log[c.commit-1].Cmd.IdemKey
		if _, ok := c.acked[key]; !ok {
			c.acked[key] = c.commit
		}
	}
	for _, id := range c.ids {
		if n := c.nodes[id]; !n.down {
			n.applyTo(c.commit)
		}
	}
}

// Crash takes a node down. Messages the leader had in transit are lost with
// it, which is the pessimistic case for asynchronous shipping.
func (c *Cluster) Crash(id string) {
	c.nodes[id].down = true
	if id == c.leader {
		c.inflight = nil
	}
}

// Rejoin brings a node back. It keeps the longest prefix that matches the
// leader's log, discards any divergent suffix, and rebuilds its state.
func (c *Cluster) Rejoin(id string) {
	n := c.nodes[id]
	n.down = false
	ll := c.nodes[c.leader]
	keep := 0
	for keep < len(n.log) && keep < len(ll.log) && n.log[keep] == ll.log[keep] {
		keep++
	}
	n.log = n.log[:keep]
	n.rebuild(c.commit)
	n.epoch = c.epoch
}
```

## Promotion, Fencing, and the Leaderless Contrast: `failover.go`, `counter.go`

```go
// failover.go
package copies

import (
	"errors"
	"fmt"
)

// Gateway is the external side of the ledger. It accepts an authorization
// only from the newest epoch it has observed, so a deposed leader cannot act.
type Gateway struct {
	highest    uint64
	authorized map[string]int64
}

func (g *Gateway) observe(epoch uint64) {
	if epoch > g.highest {
		g.highest = epoch
	}
}

func (g *Gateway) Authorize(epoch uint64, key string, amount int64) error {
	if epoch < g.highest {
		return ErrStale
	}
	g.observe(epoch)
	if _, ok := g.authorized[key]; !ok {
		g.authorized[key] = amount
	}
	return nil
}

// Failover promotes the up node with the longest log, provided the
// acknowledged entries it lacks fit within maxLoss. It returns the number of
// acknowledged entries lost. If the bound is exceeded it changes nothing.
func (c *Cluster) Failover(maxLoss uint64) (uint64, error) {
	if !c.nodes[c.leader].down {
		return 0, errors.New("leader is still up")
	}
	var best *Node
	for _, id := range c.ids {
		n := c.nodes[id]
		if n.down {
			continue
		}
		if best == nil || len(n.log) > len(best.log) {
			best = n
		}
	}
	if best == nil {
		return 0, errors.New("no node available")
	}

	bestLen := uint64(len(best.log))
	var lost uint64
	if c.commit > bestLen {
		lost = c.commit - bestLen
	}
	if lost > maxLoss {
		return lost, fmt.Errorf("%w: %d acknowledged entries missing, bound is %d",
			ErrLossBound, lost, maxLoss)
	}

	c.commit = min(c.commit, bestLen)
	c.epoch++
	c.leader = best.ID
	c.gateway.observe(c.epoch)
	for _, id := range c.ids {
		n := c.nodes[id]
		if n.down {
			continue
		}
		// Unacknowledged tail is discarded. Clients retry it with the same
		// idempotency keys, so nothing a client was told is lost by this.
		if uint64(len(n.log)) > c.commit {
			n.log = n.log[:c.commit]
		}
		n.epoch = c.epoch
		n.applyTo(c.commit)
	}
	for idx := range c.stores {
		if idx > c.commit {
			delete(c.stores, idx)
		}
	}
	c.inflight = nil
	return lost, nil
}
```

```go
// counter.go
package copies

// GCounter is a grow-only counter with one slot per node. It is the leaderless
// strategy in miniature: each node increments only its own slot, and merge
// takes the per-slot maximum, so the order and repetition of exchanges cannot
// change the converged value.
type GCounter map[string]uint64

func (g GCounter) Inc(node string) {
	g[node]++
}

func (g GCounter) Value() uint64 {
	var sum uint64
	for _, v := range g {
		sum += v
	}
	return sum
}

func (g GCounter) Merge(other GCounter) {
	for node, v := range other {
		if v > g[node] {
			g[node] = v
		}
	}
}
```

## Tests and Invariants: `copies_test.go`

The tests encode the claims from the earlier sections: a two-region policy loses nothing on a regional failure, an asynchronous policy loses exactly what the lag predicts and refuses promotion beyond its bound, retries apply once, stale epochs are fenced, and under randomized failures the invariants hold at every step.

```go
// copies_test.go
package copies

import (
	"errors"
	"fmt"
	"math/rand"
	"testing"
)

var accounts = []string{"acct-42", "acct-907"}

func twoRegionCluster(policy AckPolicy) *Cluster {
	ids := []string{"A1", "A2", "B1", "B2", "C1"}
	delay := map[string]int64{"A2": 1, "B1": 2, "B2": 3, "C1": 4}
	return NewCluster(ids, "A1", policy, delay)
}

func debit(i int) Command {
	return Command{IdemKey: fmt.Sprintf("pay-%d", i), Account: "acct-42", Amount: -int64(10 * i)}
}

func must(t *testing.T, err error) {
	t.Helper()
	if err != nil {
		t.Fatal(err)
	}
}

func sameMap[V comparable](a, b map[string]V) bool {
	if len(a) != len(b) {
		return false
	}
	for k, v := range a {
		if bv, ok := b[k]; !ok || bv != v {
			return false
		}
	}
	return true
}

func replay(log []Entry) (map[string]int64, map[string]bool) {
	bal := map[string]int64{}
	seen := map[string]bool{}
	for _, e := range log {
		if seen[e.Cmd.IdemKey] {
			continue
		}
		seen[e.Cmd.IdemKey] = true
		bal[e.Cmd.Account] += e.Cmd.Amount
	}
	return bal, seen
}

func downNodes(c *Cluster) []string {
	var out []string
	for _, id := range c.ids {
		if c.nodes[id].down {
			out = append(out, id)
		}
	}
	return out
}

// ensureLeader promotes a new leader if the current one is down, and checks
// that the old epoch is fenced at the gateway.
func ensureLeader(t *testing.T, c *Cluster, seed int64, step int) {
	t.Helper()
	if !c.nodes[c.leader].down {
		return
	}
	oldEpoch := c.Epoch()
	if _, err := c.Failover(0); err != nil {
		t.Fatalf("seed %d step %d: failover refused: %v", seed, step, err)
	}
	if err := c.Gateway().Authorize(oldEpoch, "stale-write", 1); err != ErrStale {
		t.Fatalf("seed %d step %d: epoch %d was not fenced", seed, step, oldEpoch)
	}
}

func checkInvariants(t *testing.T, c *Cluster, seed int64, step int) {
	t.Helper()
	for _, id := range c.ids {
		n := c.nodes[id]
		if n.down {
			continue
		}
		if n.applied > c.commit {
			t.Fatalf("seed %d step %d: %s applied %d beyond commit %d",
				seed, step, id, n.applied, c.commit)
		}
		bal, seen := replay(n.log[:n.applied])
		if !sameMap(bal, n.balances) || !sameMap(seen, n.seen) {
			t.Fatalf("seed %d step %d: %s state differs from its log prefix", seed, step, id)
		}
	}
	if leader := c.nodes[c.leader]; !leader.down {
		for key := range c.acked {
			if !leader.seen[key] {
				t.Fatalf("seed %d step %d: acknowledged %s missing from leader", seed, step, key)
			}
		}
	}
}

// TestTwoRegionPolicySurvivesRegionLoss: acknowledgment on leader plus one
// remote node means a single-region failure loses no acknowledged entry.
func TestTwoRegionPolicySurvivesRegionLoss(t *testing.T) {
	c := twoRegionCluster(AckPolicy{Acks: 2})
	for i := 1; i <= 5; i++ {
		_, err := c.Append(debit(i))
		must(t, err)
	}
	c.Run(10)
	if c.Commit() != 5 {
		t.Fatalf("commit = %d, want 5", c.Commit())
	}

	// Entries 6 to 8 are stored only on the leader and never acknowledged.
	for i := 6; i <= 8; i++ {
		_, err := c.Append(debit(i))
		must(t, err)
	}
	c.Crash("A1")
	c.Crash("A2")

	oldEpoch := c.Epoch()
	lost, err := c.Failover(0)
	must(t, err)
	if lost != 0 {
		t.Fatalf("lost %d acknowledged entries, want 0", lost)
	}
	if err := c.Gateway().Authorize(oldEpoch, "pay-6", -60); err != ErrStale {
		t.Fatalf("deposed leader was not fenced: %v", err)
	}

	// Clients retry the unacknowledged debits. A retry of an applied key
	// must have no further effect.
	for i := 6; i <= 8; i++ {
		_, err := c.Append(debit(i))
		must(t, err)
	}
	_, err = c.Append(debit(3))
	must(t, err)
	c.Run(10)

	leader := c.Node(c.leader)
	want := int64(-10 * (1 + 2 + 3 + 4 + 5 + 6 + 7 + 8))
	if got := leader.balances["acct-42"]; got != want {
		t.Fatalf("balance = %d, want %d (each debit applied once)", got, want)
	}

	c.Rejoin("A1")
	c.Rejoin("A2")
	c.Run(20)
	for _, id := range c.ids {
		if !sameMap(c.Node(id).balances, leader.balances) {
			t.Fatalf("%s did not converge to the leader's state", id)
		}
	}
}

// TestAsyncPolicyRequiresDeclaredBound: with acknowledgment on the leader
// alone, a failure loses exactly the entries the followers never stored.
func TestAsyncPolicyRequiresDeclaredBound(t *testing.T) {
	c := twoRegionCluster(AckPolicy{Acks: 1})
	for i := 1; i <= 3; i++ {
		_, err := c.Append(debit(i))
		must(t, err)
	}
	if c.Commit() != 3 {
		t.Fatalf("commit = %d, want 3", c.Commit())
	}
	c.Crash("A1")

	lost, err := c.Failover(0)
	if !errors.Is(err, ErrLossBound) || lost != 3 {
		t.Fatalf("zero bound: lost=%d err=%v, want 3 and ErrLossBound", lost, err)
	}
	if c.Epoch() != 1 {
		t.Fatal("refused promotion changed the epoch")
	}

	lost, err = c.Failover(5)
	must(t, err)
	if lost != 3 {
		t.Fatalf("lost = %d, want 3", lost)
	}
	for i := 1; i <= 3; i++ {
		if c.Node(c.leader).seen[debit(i).IdemKey] {
			t.Fatalf("entry %d survived promotion; the bound said it could be lost", i)
		}
	}

	// The old leader applied those debits before it failed. Rejoin must roll
	// its state back to the authoritative history.
	c.Rejoin("A1")
	if c.Node("A1").seen[debit(1).IdemKey] {
		t.Fatal("old leader still shows a debit the cluster lost")
	}
}

// TestRandomizedCopyInvariants: random appends, retries, ticks, and single
// node failures. Invariants are checked after every step.
func TestRandomizedCopyInvariants(t *testing.T) {
	for seed := int64(1); seed <= 100; seed++ {
		runCopyRandom(t, seed)
	}
}

func runCopyRandom(t *testing.T, seed int64) {
	t.Helper()
	rng := rand.New(rand.NewSource(seed))
	c := twoRegionCluster(AckPolicy{Acks: 2})
	var issued []Command
	next := 1

	for step := 0; step < 400; step++ {
		ensureLeader(t, c, seed, step)
		down := downNodes(c)

		switch r := rng.Intn(10); {
		case r < 4:
			var cmd Command
			if len(issued) > 0 && rng.Intn(3) == 0 {
				cmd = issued[rng.Intn(len(issued))] // a client retry
			} else {
				cmd = Command{
					IdemKey: fmt.Sprintf("pay-%d", next),
					Account: accounts[rng.Intn(len(accounts))],
					Amount:  -int64(10 * (1 + rng.Intn(9))),
				}
				next++
				issued = append(issued, cmd)
			}
			c.Append(cmd) // a refused write is simply retried later
		case r == 8 && len(down) == 0:
			// At most one node down at a time, so every acknowledged entry
			// keeps a copy on a surviving node. This is the policy's assumption.
			c.Crash(c.ids[rng.Intn(len(c.ids))])
		case r == 9 && len(down) > 0:
			c.Rejoin(down[0])
		default:
			c.Tick()
		}
		checkInvariants(t, c, seed, step)
	}

	ensureLeader(t, c, seed, 400)
	for _, id := range downNodes(c) {
		c.Rejoin(id)
	}
	c.Run(30)

	leader := c.nodes[c.leader]
	for _, id := range c.ids {
		n := c.nodes[id]
		if !sameMap(n.balances, leader.balances) {
			t.Fatalf("seed %d: %s balances differ from leader after convergence", seed, id)
		}
		if n.applied != c.commit {
			t.Fatalf("seed %d: %s applied %d, commit %d", seed, id, n.applied, c.commit)
		}
	}
}

// TestGCounterConverges: increments and merges in arbitrary order converge
// to the true total once every view has seen every other view.
func TestGCounterConverges(t *testing.T) {
	rng := rand.New(rand.NewSource(7))
	ids := []string{"A1", "A2", "B1", "B2", "C1"}
	views := map[string]GCounter{}
	for _, id := range ids {
		views[id] = GCounter{}
	}
	var total uint64
	for i := 0; i < 500; i++ {
		id := ids[rng.Intn(len(ids))]
		if rng.Intn(3) == 0 {
			views[id].Inc(id)
			total++
		} else {
			views[id].Merge(views[ids[rng.Intn(len(ids))]]) // repeats are harmless
		}
	}
	for pass := 0; pass < len(ids); pass++ {
		for _, a := range ids {
			for _, b := range ids {
				views[a].Merge(views[b])
			}
		}
	}
	for _, id := range ids {
		if got := views[id].Value(); got != total {
			t.Fatalf("%s converged to %d, want %d", id, got, total)
		}
	}
}
```

## How the Code Maps to the Strategies

**Acknowledgment policy.** `AckPolicy.Acks` is the whole design decision in one number. `advance` commits an index only when at least that many nodes have stored it, and the commit index is what clients are told. With `Acks: 2` the leader and one remote node must both hold an entry, which is the two-region policy from the worked example. With `Acks: 1` the client is acknowledged immediately, and the loss window is whatever the followers have not yet received.

**Asynchronous shipping with real lag.** `pump` queues each missing entry to each reachable follower with that follower's delay, and `deliver` stores it only when it extends the follower's log contiguously. Followers therefore trail the leader by their delay, and that trail is the loss window the policy declares. Dropped entries, including those lost when the leader crashes, are refilled on later ticks because `pump` looks at the actual gap, not at a remembered send position.

**Deterministic apply.** `Append` stamps `Stamp` on the leader, and `applyEntry` uses only the entry's own fields. The `seen` map gives idempotency at apply time, so a retry that lands in the log twice changes the balance once. The test checks this directly, by retrying key 3 after it has applied.

**Promotion under a declared bound.** `Failover` chooses the longest up log, computes how many acknowledged entries it lacks, and refuses if that exceeds `maxLoss`. The refusal happens before any state changes. This is the mechanism that turns the loss window from a hope into a rule: the zero-bound run refuses, and the explicitly declared bound allows promotion and reports the exact count.

**Fencing.** The `Gateway` records the highest epoch it has observed, and `Failover` raises that epoch before any write from the new leader can reach it. The old epoch is refused. Deliveries from superseded epochs are also rejected in `deliver`, so traffic from a deposed leader cannot be stored on followers.

**Rejoin with prefix matching.** `Rejoin` finds the longest prefix that matches the leader's log entry for entry, truncates the divergent suffix, and rebuilds state from the committed prefix. This is what makes the old leader's applied debits disappear in the asynchronous test. It also handles the subtle case where a rejoining node's stale tail has the same length as the leader's new history, which a length-based truncation would miss.

**Invariants.** `checkInvariants` runs after every step of the random test. It asserts that no node has applied past the commit index, that each node's state equals a replay of its own log prefix, and that every acknowledged key is present on the leader while the leader is up. Those three properties together are the copy strategy's safety claim. The random test's single-failure rule is the explicit form of the assumption the two-region policy depends on.

**The leaderless contrast.** `GCounter` shows the convergence property that the leaderless family relies on. Merge is commutative, associative, and idempotent, so the test can exchange views in any order, with repeats, and still require the true total at the end. It does not show anything about authoritative reads, which is the trade-off the earlier sections described.

## Limits of the Simulator

The model is deliberately narrow, and its limits matter for how far its results can be trusted. Commit decisions are computed by the cluster rather than by messages between nodes, so there is no election, no term per message exchange, and no real network. The one-failure-at-a-time assumption in the random test is strong, and it is the reason zero acknowledged loss is asserted. Real failures overlap, and a policy that claims to survive overlapping failures needs a different test. `Crash` drops all in-flight leader messages, which is pessimistic; a real network might deliver some of them. Snapshots, membership change, and disk durability are absent. Each of these is a place where the earlier failure stories came from, and each would need its own model before the simulator's guarantees could be relied on for production decisions.

To see the tests do their job, try a mutation. Remove the epoch check in `deliver`, and the stale-leader scenario in the random test should begin to show a follower storing traffic from a deposed epoch once a delayed delivery crosses a failover. Change `advance` to commit on the leader alone while keeping `Acks: 2` in the test, and the zero-loss assertion fails on the first regional failure. A test that does not fail under a mutation like these is not yet testing what the policy claims.

Key takeaway: The simulator turns each replication strategy into a checkable rule: the acknowledgment count sets the loss window, asynchronous shipping makes that window measurable, promotion refuses to proceed beyond the declared bound, fencing stops a deposed leader at the gateway, rejoin rebuilds state from the authoritative prefix, and randomized invariant checks confirm after every step that no acknowledged payment disappears and every copy agrees with its own log.

# Common Replication Mistakes, and How to Catch Each One

Replication failures seldom come from ignorance of the mechanisms. Teams know that quorums overlap, that asynchronous copies lag, and that conflicts need resolving. The mistakes come from stating a guarantee that nobody measured, from a rule that held in the design review and was bypassed during an incident, or from a test suite that exercised one failure at a time. This section covers seven recurring mistakes. For each, it describes how the failure appears at Kestrel, our 5-node, 3-region payments ledger, and how to catch it before a customer does. Where a check is best written in code, the example is in Go.

## 1. Declaring an Acknowledgment Policy Without Measuring Its Loss Window

The most common mistake is choosing asynchronous or semi-synchronous acknowledgment and recording a loss bound that nobody has checked against the lag the network actually produces. The policy document says "near-zero loss," the lag dashboard shows a few milliseconds on a normal day, and the bound is treated as settled.

The failure appears during the first sustained degradation. A cross-region link slows, lag climbs past the bound, and the next leader failure loses acknowledged payments that the design said could not be lost. Kestrel's version of this story was a debit window of about 2,000 entries, discovered during reconciliation rather than during the design review.

To catch it, the policy must be checked against measured lag, not assumed. A declared bound should be a function that fails the deployment or the policy review when the measured tail exceeds it:

```go
func (p CopyPolicy) Check(measuredLagP99 time.Duration) error {
    if p.Acks == 1 && p.MaxLossTime == 0 {
        return errors.New("asynchronous acknowledgment requires a declared loss bound")
    }
    if p.Acks == 1 && measuredLagP99 > p.MaxLossTime {
        return fmt.Errorf("p99 lag %v exceeds declared bound %v", measuredLagP99, p.MaxLossTime)
    }
    return nil
}
```

Run this check continuously against the live lag metric, not once at launch. Add a second check that injects a realistic degradation into the link and confirms that the alert fires before the bound is crossed, not after.

## 2. Promoting the Node That Is Available Rather Than the Node That Is Current

Failover logic often selects a new leader by reachability and health, not by how much of the acknowledged history it holds. A node that answers health checks quickly may be the one that lags most, because it sits on the slowest link. Promoting it accepts a loss that the controller never checked.

Kestrel's version appeared when the failover controller picked the first healthy follower in its configuration list. That node was 40 seconds behind the acknowledgment watermark, and the controller did not compare it against the watermark or the declared bound. The loss was silent until reconciliation.

The catch is a failover test that asserts a refusal, not only a success. Build a drill in which the most current node is unhealthy and the least current node is responsive, and assert that the controller either promotes the most current node once it recovers or refuses to promote beyond the bound. The check in the simulator's `Failover`, which returns `ErrLossBound` before any state changes, is the pattern to copy. The drill should also confirm that the refusal leaves the epoch unchanged, so that a retry after a refusal is not a split decision.

## 3. Fencing Only the Happy Path

Teams usually fence the new leader's epoch in the storage layer and stop there. The external systems that receive ledger output, such as card-network gateways, settlement files, and notification services, often accept requests from anyone holding valid credentials. A paused or partitioned former leader that resumes can then produce effects the cluster has already superseded.

The failure is hard to see in ordinary operation because the old leader is usually dead. It shows up when a process is paused for longer than the failure detector's timeout, then resumes and continues sending as if nothing happened. In one Kestrel incident, a former leader resumed after a long garbage-collection pause and issued authorizations for about 40 seconds before its outbound calls were refused, because the gateway had not been updated with the new epoch.

To catch this, inject pauses. Stop the leader's process with a signal that freezes it, wait past the detection window, promote a new leader, then resume the old one and assert that every external system refuses its requests. The simulator's test does this at the gateway level. The production equivalent is a pause injector that runs against a staging cluster with the real external adapters, and the assertion is on the external system's refusal count, not on the cluster's internal state.

## 4. Sending External Effects Before Commit

Designs often send a notification, a card-network authorization, or a settlement instruction as soon as the leader applies an entry locally, rather than after the commit index covers it. The effect then exists outside the cluster before the cluster has decided it is real. When the entry is later truncated during a failover, the outside world holds a payment the ledger does not.

Kestrel's version was an early authorization path that forwarded debits on local append for latency. A failover discarded the unacknowledged tail, and the card network held authorizations for debits that the ledger never recorded. The repair took a manual reconciliation of settlement files against the ledger, and it required contacting the card network to void the authorizations.

The catch has two parts. The first is a code-level invariant: every call to an external adapter must be dominated by a check that the entry's index is at or below the commit index, and a test should exercise the path with a non-committed entry and assert that nothing is sent. The second is a trace audit: record each external effect with the index it derived from, and check after every failover drill that no external effect references an index above the final commit index. If that audit finds even one, the design has a defect regardless of whether the reconciliation happened to catch it.

## 5. Allowing Nondeterminism in the Apply Path

Log shipping works only if applying the same log on two nodes produces the same state. Teams break this by reading the local clock, generating identifiers, or consulting local tables inside the apply function. The nodes then diverge while each remains internally consistent, so the divergence goes unnoticed until someone compares totals.

Kestrel's version was a fee calculation that read a currency rate from a local table. Two nodes applied the same debit against different rates and ended with different balances. The repair required rebuilding nodes from snapshots.

The catch is a determinism test. Replay a recorded log on several fresh nodes, give each a different clock offset and a different environment, and compare a hash of the resulting state. Make the test fail if any value differs:

```go
func TestApplyIsDeterministic(t *testing.T) {
    log := recordedLedgerLog(t) // a committed history captured from staging
    var want string
    for i, offset := range []time.Duration{0, 3 * time.Second, -90 * time.Second} {
        n := newNodeWithClock(offset) // each node's clock disagrees
        for _, e := range log {
            n.applyEntry(e)
        }
        got := stateHash(n)
        if i == 0 {
            want = got
        } else if got != want {
            t.Fatalf("clock offset %v produced a different state", offset)
        }
    }
}
```

Pair the test with a static rule. Packages that contain apply logic should not import the clock, random sources, or network clients, and a lint check or build rule should enforce this.

## 6. Choosing Conflict Semantics by Convenience

Multi-leader designs require a conflict rule, and the rule is often chosen for simplicity. Last-writer-wins by wall-clock time is the usual choice, and it silently discards updates when clocks disagree. Merge functions chosen without regard to the data's structure are the other common error, as the merchant fee schedule story showed: a union of rules that were only meaningful together.

Kestrel's version of the second case produced a fee schedule with a refund window from one edit and a fee from another. The schedule was accepted by the system, and nothing flagged that it was incoherent.

The catch depends on the kind of error. For clock-based conflicts, inject skew in both directions and run concurrent updates to the same key from skewed clients, asserting that no acknowledged update disappears unless the rule explicitly allows it. For merge functions, test the algebraic laws. A merge that is not commutative, associative, and idempotent will produce results that depend on exchange order, and a property test will find that quickly:

```go
func TestMergeLaws(t *testing.T) {
    for i := 0; i < 1000; i++ {
        a, b, c := randomView(), randomView(), randomView()
        if !equal(merge(a, b), merge(b, a)) {
            t.Fatal("merge is not commutative")
        }
        if !equal(merge(merge(a, b), c), merge(a, merge(b, c))) {
            t.Fatal("merge is not associative")
        }
        if !equal(merge(a, a), a) {
            t.Fatal("merge is not idempotent")
        }
    }
}
```

Laws alone do not prove the merge is correct. A merge can satisfy them and still produce an incoherent schedule. The second check is a domain invariant on the merged result, such as "the refund window and the fee must come from the same edit," asserted after every merge in the property test. Fields that fail this check belong on the single-leader path, where conflicts cannot arise.

## 7. Treating Convergence as an Assumption

Copies diverge, and the repair mechanisms bring them back together, but teams often never measure how long that takes or whether the repair mechanisms outlast the outage they are meant to cover. Three specific errors recur. Hint retention is set shorter than the longest outage, so hinted writes expire before the node returns. Anti-entropy runs on a nightly schedule and is never triggered by a rejoin. And quorum sizes are tuned for latency with the assumption that repair will catch up, without anyone checking when it does.

Kestrel's settlement-report incident was all three at once: a three-hour maintenance window, a two-hour hint limit, and nightly repair. The report was missing a block of entries for a day.

The catch is a rejoin drill with a convergence target. Take a node down for longer than the longest planned window, bring it back, and measure the time until its summary matches the leader's. Alert if the time exceeds the target for that data type. Add two more checks that are easy to forget: a metric for hints that expired undelivered, and a job that runs after every rejoin, not only on schedule. Expired hints should be treated as a data-loss event until proven otherwise.

Quorum tuning deserves its own check. Write a test that issues concurrent writes and reads against a leaderless configuration and runs a linearizability checker on the history. Teams that assume `R + W > N` gives linearizability will find that it does not, and the test is the only reliable way to discover the gap before a customer does.

## The Common Thread

Each of these mistakes replaces a checked property with an assumed one. The bound is assumed to hold, the most current node is assumed to be the one promoted, the old leader is assumed to be silent, the external effect is assumed to follow commit, the apply path is assumed to be deterministic, the merge is assumed to be correct, and convergence is assumed to finish in time. The reconciliation check at the end of the sequence is valuable, but it is the last line of defense, and it finds problems after the damage is done.

The discipline that catches all seven is the same as in the earlier sections. Write each property as a check that can fail: a function that rejects a policy, a drill that asserts a refusal, a pause injector that asserts the external system's response, a trace audit that finds external effects above the commit index, a determinism test across skewed clocks, a property test for merge laws with a domain invariant, and a rejoin drill with a convergence target. Run these continuously, not at launch, and treat a failing check as a defect in the design rather than a flaky test.

Key takeaway: The most common replication mistakes are undeclared loss windows, promotion without checking the acknowledgment watermark, fencing that stops at the cluster's edge, external effects sent before commit, nondeterministic apply logic, convergence rules chosen for convenience, and convergence times that nobody measured, and each is caught by turning the assumed property into a check that can fail, run against live lag, pause injection, trace audits, determinism replays, merge laws, and rejoin drills.

# Five Concepts Behind Sharding and Partitioning

The overview introduced partitions, directories, and cross-partition operations as vocabulary. Working with them in production requires understanding the mechanisms that make them safe and the specific ways they fail. This section covers five concepts that carry most of the weight. Kestrel, our payments ledger, supplies the examples, with each partition being a five-node copy group across three regions. The code fragments are in Go and are sketches for discussion, not compiled code.

## 1. The Partition Key Decides What Is Local

The partition key determines which operations can be served entirely within one partition, and that determines which guarantees are cheap and which are expensive. An operation that touches only data owned by one partition inherits that partition's consensus and failover behavior at no extra cost. An operation that touches two partitions needs a protocol to coordinate them, which costs latency, failure handling, and testing effort.

For Kestrel, the account identifier is the natural key for balance operations. A debit or credit touches one account, so it is local, and its ordering and overdraft check are handled by a single copy group. But a payment touches a customer account, a merchant account, and a settlement record, and the merchant's operational view needs every payment to that merchant. Keying by customer makes customer views local and merchant views scattered. Keying by merchant does the reverse. No single key makes every common operation local, so the design must rank the operations by frequency and by business criticality, and choose the key that makes the most critical ones local.

The practical technique is to write down the operation list before choosing the key. For each operation, record which keys it touches and whether it must be atomic. Operations that must be atomic and touch more than one key are the cost of the choice, and each one should be justified. A key that makes an atomic multi-account operation common is a design smell, because every such operation becomes a cross-partition transaction. Where a related set of records must always be co-located, a design can group them under a shared key, such as an account family or a customer identifier, and treat that group as the unit of locality.

## 2. Slot Indirection Makes Rebalancing Possible

The simplest partition function is a hash modulo the number of partitions. It spreads keys evenly, but it couples every key's location to the partition count. When the count changes from 8 to 9, the mapping changes for most keys, and a rebalance must move most of the data. That is an expensive and risky operation to perform on a ledger.

Slot indirection separates the two decisions. Keys hash to a fixed number of slots, which never changes, and a directory maps each slot to its owning partition, which can change. A rebalance moves only the slots whose owner changes, and the key-to-slot mapping stays fixed.

```go
const slotCount = 1024

func slotOf(key string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(key))
	return h.Sum32() % slotCount
}

// modOwner is the approach to avoid: changing n remaps most keys.
func modOwner(key string, n uint32) uint32 {
	h := fnv.New32a()
	h.Write([]byte(key))
	return h.Sum32() % n
}
```

The choice of slot count is a trade-off. Too few slots and each slot holds so much data that moving one is slow and lumpy. Too many and the directory becomes large and every routing decision carries more state. For Kestrel, a few thousand slots keeps individual moves to a manageable size while the directory remains small enough to cache on every client. The slot count is fixed for the life of the system, so it should be chosen with growth in mind. Changing it later requires a full remapping, which defeats the purpose.

Consistent hashing is the alternative most people encounter first. It also limits movement when nodes change, but it spreads ownership across a ring of positions, which makes it harder to control which data moves together and harder to fence a single range during a move. For a ledger that needs explicit ownership records and epoch-checked moves, fixed slots with an explicit directory are easier to reason about and to audit.

## 3. Rebalancing Is a Fenced Handoff, Not a Copy

Moving a slot from one partition to another is the most dangerous operation in a partitioned system. The data must be copied, the writes that arrived during the copy must be caught up, and ownership must switch in a single step that the old owner cannot contest. Each step has a failure mode that loses or duplicates money.

The safe sequence is a state machine. The slot is copied while the old owner continues to accept writes. The new owner then catches up on the log entries the old owner accepted after the copy began. The old owner is fenced, which means it stops accepting writes for the slot and returns a redirect carrying the new epoch. Once the new owner has every entry up to the fence, the directory is updated, its epoch is incremented, and the new owner begins accepting writes.

```go
type MoveStage int

const (
	Copying MoveStage = iota
	CatchingUp
	Fenced
	Switched
)

type SlotMove struct {
	Slot     uint32
	From, To string
	Stage    MoveStage
	FenceAt  uint64 // last log index the old owner will ever accept for the slot
}

// Advance moves the state machine forward only when the step's precondition
// holds. The fence index is what makes the handoff exact: nothing above it is
// accepted by the old owner, and nothing below it can be missing at the new one.
func (m *SlotMove) Advance(oldOwnerApplied, newOwnerApplied uint64) error {
	switch m.Stage {
	case Copying:
		m.Stage = CatchingUp
	case CatchingUp:
		if newOwnerApplied < oldOwnerApplied {
			return errors.New("new owner still catching up")
		}
		m.FenceAt = oldOwnerApplied
		m.Stage = Fenced
	case Fenced:
		if newOwnerApplied < m.FenceAt {
			return errors.New("new owner has not reached the fence")
		}
		m.Stage = Switched
	}
	return nil
}
```

The key invariant is that the directory switch and the epoch increment happen only after the new owner holds every entry up to the fence. A switch before that loses writes. A switch without a fence allows the old owner to accept writes the new owner never sees. Both errors are silent until a reconciliation finds a balance that does not match, which is why the rebalancing tests should check the ledger totals of the moved slot before and after, not only whether the move completed.

Routing must enforce the epoch. Every request carries the epoch under which the client routed it, and every partition refuses a request for a slot it does not currently own, or whose epoch does not match its view. The client then refreshes its directory and retries. Without this check, a client with an outdated directory can write to the old owner after the switch, and the write is accepted because the old owner still has the slot in its memory.

## 4. Hot Keys Are Not Solved by Hashing

Hash partitioning spreads distinct keys evenly, and it does nothing for a single key that receives a disproportionate share of traffic. A large merchant's account, or a settlement account that collects fees from every transaction, can saturate the partition that holds it while the other partitions sit idle. The partition is hot because one key is hot, and moving the key to another partition moves the saturation with it.

The first step is measurement. Track request rates per key and per slot, not only per partition, and alert on keys whose share of their partition's traffic exceeds a threshold. A partition whose load comes from one key needs a different remedy than a partition whose load is spread across many keys.

The remedy for a hot key is splitting its state across sub-keys. A settlement account, for example, can be divided into eight sub-ledgers, each receiving a fraction of the increments and owned by a different slot. Writes are spread across sub-ledgers, and reads sum them.

```go
const subLedgers = 8

// subLedgerKey spreads writes for a hot account across sub-ledgers, which
// map to different slots and so possibly different partitions.
func subLedgerKey(account string, shard int) string {
	return fmt.Sprintf("%s#%d", account, shard%subLedgers)
}

// Balance sums the sub-ledgers. Reads now touch several partitions, so the
// total is a cross-partition read and must be labeled as one.
func Balance(ctx context.Context, account string, read func(string) (int64, error)) (int64, error) {
	var total int64
	for i := 0; i < subLedgers; i++ {
		v, err := read(fmt.Sprintf("%s#%d", account, i))
		if err != nil {
			return 0, err
		}
		total += v
	}
	return total, nil
}
```

Splitting has a price, and it lands on invariants. An overdraft rule that applies to the whole account can no longer be enforced by one sub-ledger's check, because no sub-ledger sees the total. Either the rule is relaxed to a per-sub-ledger floor with a documented bound on overdraft, or the check becomes a cross-partition read followed by a conditional write, which is only correct under the transaction protocols covered in the next section. Splitting therefore needs a business decision about the invariant, not only an engineering change to the key.

## 5. Cross-Partition Reads Trade Completeness for Availability

Reads that span partitions, such as a merchant's total volume for the day, have two standard implementations, and each has a characteristic failure. Scatter-gather sends the query to every partition and combines the results. It reflects current data, but it is only as available as the slowest partition, and a partition that does not answer makes the total incomplete. A maintained view, built from each partition's committed log, is fast to read, but it lags the source by an amount that must be stated and monitored.

Scatter-gather must not present a partial total as complete. The response should carry the set of partitions that answered and the set that did not, so that the caller can label the result. This is the harvest-and-yield idea from the earlier discussion, applied to a sharded query.

```go
type TotalResult struct {
	Sum        int64
	Answered   []string // partitions that contributed
	Unanswered []string // partitions that did not respond in time
}

func (r TotalResult) Complete() bool {
	return len(r.Unanswered) == 0
}
```

Secondary indexes follow the same logic. A local index lives inside each partition and covers only that partition's records, which makes writes cheap but a query by merchant must touch every partition. A global index lives in its own structure and covers all partitions, which makes merchant queries cheap but requires each write to update an index that belongs to another partition. For Kestrel, merchant queries are frequent enough to justify a global index built as a projection from the committed log. Its lag is part of the contract, and its freshness should be reported the same way as any other derived view. Administrative totals that run rarely can use scatter-gather, with the partial-result labeling above.

## Connecting the Concepts

These five concepts form one chain. The partition key decides which operations are local. Slot indirection lets the key-to-owner mapping change without moving everything. A fenced handoff makes those changes safe. Hot keys show where the mapping's assumption of even distribution fails, and splitting them changes which invariants can be enforced. And cross-partition reads show what the design gives up when operations span partitions. Each step depends on the previous one, and a change at any point, such as a new key or a new hot account, can affect the others. The next section takes the operations that do span partitions and asks how transfers between them can commit atomically.

Key takeaway: Sharding works when the partition key makes the critical operations local, slot indirection decouples data placement from partition count, rebalancing is a fenced handoff validated by ledger totals rather than by completion alone, hot keys require splitting that must be paired with an explicit decision about the invariants they break, and cross-partition reads must say which partitions they could not reach, so that Kestrel's capacity can grow by adding partitions without silently changing what any balance means.

This version renames the server type from `Partition` to `Node`, per the standing terminology rule. The code is a model, not a production system, and I have not compiled or run it in this session.

# A Sharded Ledger in Go: Slots, Fenced Moves, and Conservation Checks

Kestrel's accounts are spread across slots, and each slot has one owning node. The owners in this example are A1 (slots 0 to 511) and B1 (slots 512 to 1023), with C1 initially empty. In the full layout, each owner stands for the leader-facing node of a five-node copy group spanning regions A, B, and C. Those groups are outside this package. The code models only how slots are routed, moved, and checked.

## The Directory: `directory.go`

```go
// directory.go
package sharding

import "hash/fnv"

const SlotCount = 1024

// SlotOf maps an account to a slot. The mapping never changes, so rebalancing
// moves slots between nodes, not individual accounts.
func SlotOf(account string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(account))
	return h.Sum32() % SlotCount
}

// Directory is the authoritative slot-to-node map. Every ownership change
// increments Epoch, and requests carry the epoch their router last saw.
type Directory struct {
	Epoch uint64
	owner [SlotCount]string
}

func (d *Directory) Assign(slot uint32, node string) { d.owner[slot] = node }
func (d *Directory) Owner(slot uint32) string        { return d.owner[slot] }

// Snapshot returns a copy, which is what a router holds as its view.
func (d *Directory) Snapshot() Directory { return *d }

// Reassign changes a slot's owner and returns the new epoch.
func (d *Directory) Reassign(slot uint32, node string) uint64 {
	d.owner[slot] = node
	d.Epoch++
	return d.Epoch
}
```

## The Node: `node.go`

```go
// node.go
package sharding

import "errors"

var (
	ErrWrongOwner = errors.New("slot not owned by this node")
	ErrFenced     = errors.New("slot fenced for handoff; retry after switch")
	ErrStaleView  = errors.New("request routed under an outdated directory")
)

type Request struct {
	Key       string // idempotency key chosen by the client
	Account   string
	Amount    int64
	ViewEpoch uint64 // directory epoch the router last saw
}

// Entry is one movement. Index is this node's own log position and is the
// cursor for catch-up. Key travels with the entry so retries stay idempotent
// after the slot moves.
type Entry struct {
	Index   uint64
	Key     string
	Account string
	Amount  int64
}

type applied struct {
	index uint64
	slot  uint32
}

type Node struct {
	ID       string
	next     uint64
	log      []Entry
	owned    map[uint32]uint64 // slot -> epoch at which this node took it
	fenced   map[uint32]bool
	balances map[string]int64
	seen     map[string]applied // idempotency key -> where it was applied
	cursor   map[uint32]uint64  // slot -> highest source index imported
}

func NewNode(id string) *Node {
	return &Node{
		ID:       id,
		owned:    map[uint32]uint64{},
		fenced:   map[uint32]bool{},
		balances: map[string]int64{},
		seen:     map[string]applied{},
		cursor:   map[uint32]uint64{},
	}
}

// Accept applies a movement only if this node owns the slot, the slot is not
// fenced, and the router's view is not older than this node's ownership. A
// repeated key returns the original index and changes nothing.
func (n *Node) Accept(req Request) (uint64, error) {
	slot := SlotOf(req.Account)
	ep, owns := n.owned[slot]
	switch {
	case !owns:
		return 0, ErrWrongOwner
	case n.fenced[slot]:
		return 0, ErrFenced
	case req.ViewEpoch < ep:
		return 0, ErrStaleView
	}
	if rec, dup := n.seen[req.Key]; dup {
		return rec.index, nil
	}
	return n.appendEntry(req.Key, req.Account, req.Amount), nil
}

func (n *Node) appendEntry(key, account string, amount int64) uint64 {
	n.next++
	n.log = append(n.log, Entry{Index: n.next, Key: key, Account: account, Amount: amount})
	n.balances[account] += amount
	n.seen[key] = applied{index: n.next, slot: SlotOf(account)}
	return n.next
}

// Slice returns the slot's entries above a source index, in log order.
func (n *Node) Slice(slot uint32, after uint64) []Entry {
	var out []Entry
	for _, e := range n.log {
		if e.Index > after && SlotOf(e.Account) == slot {
			out = append(out, e)
		}
	}
	return out
}

// Fence stops new writes to the slot and returns the log position at which it
// took effect. Nothing for the slot can be appended above that position.
func (n *Node) Fence(slot uint32) uint64 {
	n.fenced[slot] = true
	return n.next
}

// Import applies source entries this node has not yet seen. Re-delivery is
// harmless: the cursor skips entries already applied, and the key check skips
// entries whose key is already recorded.
func (n *Node) Import(slot uint32, entries []Entry) {
	for _, e := range entries {
		if e.Index <= n.cursor[slot] {
			continue
		}
		n.cursor[slot] = e.Index
		if _, dup := n.seen[e.Key]; dup {
			continue
		}
		n.appendEntry(e.Key, e.Account, e.Amount)
	}
}

func (n *Node) Cursor(slot uint32) uint64 { return n.cursor[slot] }

// ClearSlot removes all state for a slot. A node that held the slot in an
// earlier epoch may hold stale data, so every copy starts from empty.
func (n *Node) ClearSlot(slot uint32) {
	kept := n.log[:0]
	for _, e := range n.log {
		if SlotOf(e.Account) != slot {
			kept = append(kept, e)
		}
	}
	n.log = kept
	for acct := range n.balances {
		if SlotOf(acct) == slot {
			delete(n.balances, acct)
		}
	}
	for key, rec := range n.seen {
		if rec.slot == slot {
			delete(n.seen, key)
		}
	}
	delete(n.cursor, slot)
	delete(n.fenced, slot)
}

func (n *Node) Own(slot uint32, epoch uint64) {
	n.owned[slot] = epoch
	delete(n.fenced, slot)
}

func (n *Node) Disown(slot uint32) {
	delete(n.owned, slot)
	delete(n.fenced, slot)
}

func (n *Node) Balance(account string) int64 { return n.balances[account] }

func (n *Node) SlotTotal(slot uint32) int64 {
	var sum int64
	for acct, v := range n.balances {
		if SlotOf(acct) == slot {
			sum += v
		}
	}
	return sum
}
```

## Routing: `router.go`

```go
// router.go
package sharding

import "errors"

// Router holds a client's view of the directory. It sends each write to the
// owner in that view. On a redirect it refreshes the view and retries. A
// fenced slot is not redirected: the caller must back off until the switch.
type Router struct {
	dir       *Directory
	view      Directory
	nodes     map[string]*Node
	Redirects int
}

func NewRouter(dir *Directory, nodes map[string]*Node) *Router {
	return &Router{dir: dir, view: dir.Snapshot(), nodes: nodes}
}

func (r *Router) Refresh() { r.view = r.dir.Snapshot() }

func (r *Router) Write(key, account string, amount int64) (uint64, error) {
	for attempt := 0; attempt < 3; attempt++ {
		n := r.nodes[r.view.Owner(SlotOf(account))]
		idx, err := n.Accept(Request{Key: key, Account: account, Amount: amount, ViewEpoch: r.view.Epoch})
		if err == nil {
			return idx, nil
		}
		if errors.Is(err, ErrWrongOwner) || errors.Is(err, ErrStaleView) {
			r.Redirects++
			r.Refresh()
			continue
		}
		return 0, err
	}
	return 0, errors.New("routing did not converge")
}
```

## The Move: `rebalance.go`

```go
// rebalance.go
package sharding

import (
	"errors"
	"fmt"
)

type stage int

const (
	stageNew stage = iota
	stageCopied
	stageCaughtUp
	stageFenced
	stageVerified
	stageSwitched
)

// Move transfers one slot between nodes. Each method checks the stage it
// requires, so the protocol cannot run out of order.
type Move struct {
	Slot     uint32
	From, To string
	stage    stage
	dir      *Directory
	nodes    map[string]*Node
	fenceAt  uint64
}

func NewMove(dir *Directory, nodes map[string]*Node, slot uint32, to string) (*Move, error) {
	from := dir.Owner(slot)
	if from == to {
		return nil, fmt.Errorf("slot %d already owned by %s", slot, to)
	}
	if _, ok := nodes[to]; !ok {
		return nil, fmt.Errorf("unknown node %s", to)
	}
	return &Move{Slot: slot, From: from, To: to, dir: dir, nodes: nodes}, nil
}

func (m *Move) src() *Node { return m.nodes[m.From] }
func (m *Move) dst() *Node { return m.nodes[m.To] }

// Copy clears the destination and imports a snapshot. Writes continue on the
// source, so the snapshot is a starting point, not the final state.
func (m *Move) Copy() error {
	if m.stage != stageNew {
		return errors.New("copy must be the first step")
	}
	m.dst().ClearSlot(m.Slot)
	m.dst().Import(m.Slot, m.src().Slice(m.Slot, 0))
	m.stage = stageCopied
	return nil
}

// CatchUp imports source entries accepted since the destination's cursor. It
// may repeat while live traffic continues.
func (m *Move) CatchUp() error {
	if m.stage != stageCopied && m.stage != stageCaughtUp {
		return errors.New("catch-up requires a copy")
	}
	m.dst().Import(m.Slot, m.src().Slice(m.Slot, m.dst().Cursor(m.Slot)))
	m.stage = stageCaughtUp
	return nil
}

// Fence stops writes on the source, then imports the remainder, so the
// destination holds every entry up to the fence position.
func (m *Move) Fence() error {
	if m.stage != stageCopied && m.stage != stageCaughtUp {
		return errors.New("fence requires a copy")
	}
	m.fenceAt = m.src().Fence(m.Slot)
	m.dst().Import(m.Slot, m.src().Slice(m.Slot, m.dst().Cursor(m.Slot)))
	m.stage = stageFenced
	return nil
}

// Verify compares the money on both sides. Completion alone proves nothing.
// Matching totals and an empty tail above the fence are the evidence.
func (m *Move) Verify() error {
	if m.stage != stageFenced {
		return errors.New("verify requires a fence")
	}
	if len(m.src().Slice(m.Slot, m.fenceAt)) != 0 {
		return fmt.Errorf("slot %d accepted writes after its fence", m.Slot)
	}
	want, got := m.src().SlotTotal(m.Slot), m.dst().SlotTotal(m.Slot)
	if want != got {
		return fmt.Errorf("slot %d: source holds %d, destination holds %d", m.Slot, want, got)
	}
	m.stage = stageVerified
	return nil
}

// Switch gives the destination ownership at a new epoch, updates the
// directory, and retires the source. The destination owns the slot before the
// directory names it, so any request routed by the new directory finds an owner.
func (m *Move) Switch() error {
	if m.stage != stageVerified {
		return errors.New("switch requires verification")
	}
	newEpoch := m.dir.Epoch + 1
	m.dst().Own(m.Slot, newEpoch)
	m.dir.Reassign(m.Slot, m.To)
	m.src().Disown(m.Slot)
	m.stage = stageSwitched
	return nil
}
```

## Hot Keys and Scatter-Gather: `scatter.go`

```go
// scatter.go
package sharding

import "fmt"

// SubAccount spreads a hot merchant account across sub-ledgers. Each
// sub-account hashes to its own slot, so its writes distribute across nodes.
// An overdraft floor then needs a cross-node check, because no single
// sub-ledger sees the whole balance.
func SubAccount(account string, shard int) string {
	return fmt.Sprintf("%s#%d", account, shard)
}

type Total struct {
	Sum      int64
	Answered []string // owners that contributed
	Missing  []string // owners that were unreachable
}

func (t Total) Complete() bool { return len(t.Missing) == 0 }

// MerchantTotal sums each account at its current owner. An unreachable owner
// is listed rather than skipped, so a partial sum is never presented as complete.
func MerchantTotal(dir *Directory, nodes map[string]*Node, reachable map[string]bool, accounts []string) Total {
	var t Total
	answered := map[string]bool{}
	missing := map[string]bool{}
	for _, acct := range accounts {
		owner := dir.Owner(SlotOf(acct))
		if !reachable[owner] {
			if !missing[owner] {
				missing[owner] = true
				t.Missing = append(t.Missing, owner)
			}
			continue
		}
		if !answered[owner] {
			answered[owner] = true
			t.Answered = append(t.Answered, owner)
		}
		t.Sum += nodes[owner].Balance(acct)
	}
	return t
}
```

## Tests: `sharding_test.go`

```go
// sharding_test.go
package sharding

import (
	"errors"
	"fmt"
	"math/rand"
	"testing"
)

func must(t *testing.T, err error) {
	t.Helper()
	if err != nil {
		t.Fatal(err)
	}
}

// newKestrelCluster starts with A1 owning even slots and B1 owning odd slots.
// C1 exists but owns nothing, so the first move has a fresh destination.
func newKestrelCluster() (*Directory, map[string]*Node) {
	dir := &Directory{}
	nodes := map[string]*Node{"A1": NewNode("A1"), "B1": NewNode("B1"), "C1": NewNode("C1")}
	for s := uint32(0); s < SlotCount; s++ {
		owner := "A1"
		if s%2 == 1 {
			owner = "B1"
		}
		dir.Assign(s, owner)
		nodes[owner].Own(s, 0)
	}
	return dir, nodes
}

func TestFencedStaleRoutingAndHarvest(t *testing.T) {
	dir := &Directory{}
	nodes := map[string]*Node{"A1": NewNode("A1"), "B1": NewNode("B1")}
	for s := uint32(0); s < SlotCount; s++ {
		dir.Assign(s, "A1")
		nodes["A1"].Own(s, 0)
	}

	acct := "acct-42"
	slot := SlotOf(acct)
	client := NewRouter(dir, nodes)
	_, err := client.Write("k1", acct, 500)
	must(t, err)

	move, err := NewMove(dir, nodes, slot, "B1")
	must(t, err)
	must(t, move.Copy())
	_, err = client.Write("k2", acct, 100) // accepted during catch-up
	must(t, err)
	must(t, move.CatchUp())
	must(t, move.Fence())

	stale := NewRouter(dir, nodes)
	if _, err := stale.Write("k3", acct, 25); !errors.Is(err, ErrFenced) {
		t.Fatalf("write to fenced slot: got %v, want ErrFenced", err)
	}
	must(t, move.Verify())
	must(t, move.Switch())

	_, err = stale.Write("k3", acct, 25)
	must(t, err)
	if stale.Redirects != 1 {
		t.Fatalf("redirects = %d, want 1", stale.Redirects)
	}
	if got := nodes["B1"].Balance(acct); got != 625 {
		t.Fatalf("balance on new owner = %d, want 625", got)
	}

	// A retry of an applied key after the move must change nothing.
	_, err = stale.Write("k1", acct, 500)
	must(t, err)
	if got := nodes["B1"].Balance(acct); got != 625 {
		t.Fatalf("retry changed balance to %d", got)
	}

	// Hot-key sub-ledgers: the total is a cross-node read that labels any
	// owner it could not reach.
	var subs []string
	for i := 0; i < 8; i++ {
		sub := SubAccount("merchant-settle", i)
		subs = append(subs, sub)
		_, err := client.Write(fmt.Sprintf("s%d", i), sub, 10)
		must(t, err)
	}
	all := MerchantTotal(dir, nodes, map[string]bool{"A1": true, "B1": true}, subs)
	if !all.Complete() || all.Sum != 80 {
		t.Fatalf("total = %d complete=%v, want 80 complete", all.Sum, all.Complete())
	}

	other := "acct-0"
	if SlotOf(other) == slot {
		other = "acct-1"
	}
	partial := MerchantTotal(dir, nodes, map[string]bool{"A1": true}, []string{acct, other})
	if partial.Complete() || len(partial.Missing) != 1 || partial.Missing[0] != "B1" {
		t.Fatalf("partial total not labeled: %+v", partial)
	}
}

func TestRandomizedRebalanceConservesMoney(t *testing.T) {
	for seed := int64(1); seed <= 200; seed++ {
		runRebalance(t, seed)
	}
}

type pendingWrite struct {
	key, account string
	amount       int64
}

func runRebalance(t *testing.T, seed int64) {
	t.Helper()
	rng := rand.New(rand.NewSource(seed))
	dir, nodes := newKestrelCluster()
	ids := []string{"A1", "B1", "C1"}
	routers := []*Router{NewRouter(dir, nodes), NewRouter(dir, nodes)}
	expected := map[uint32]int64{}
	touched := map[uint32]bool{}
	var pending []pendingWrite
	var active *Move
	nextKey := 0

	for step := 0; step < 400; step++ {
		switch r := rng.Intn(10); {
		case r < 5:
			var w pendingWrite
			if len(pending) > 0 && rng.Intn(2) == 0 {
				w, pending = pending[0], pending[1:]
			} else {
				w = pendingWrite{
					key:     fmt.Sprintf("k%d", nextKey),
					account: fmt.Sprintf("acct-%d", rng.Intn(24)),
					amount:  int64(rng.Intn(201) - 100),
				}
				nextKey++
			}
			if _, err := routers[rng.Intn(2)].Write(w.key, w.account, w.amount); err == nil {
				expected[SlotOf(w.account)] += w.amount
				touched[SlotOf(w.account)] = true
			} else {
				pending = append(pending, w) // refused writes are retried later
			}
		case r == 5 && active == nil:
			slot := uint32(rng.Intn(SlotCount))
			if m, err := NewMove(dir, nodes, slot, ids[rng.Intn(len(ids))]); err == nil {
				active = m
			}
		case r < 8 && active != nil:
			if err := advanceMove(active, rng); err != nil {
				t.Fatalf("seed %d step %d: %v", seed, step, err)
			}
		case r == 8:
			routers[rng.Intn(2)].Refresh()
		}
		if active != nil && active.stage == stageSwitched {
			active = nil
		}
		checkConservation(t, seed, step, dir, nodes, expected, touched)
	}

	for active != nil {
		if err := advanceMove(active, rng); err != nil {
			t.Fatalf("seed %d: finishing move: %v", seed, err)
		}
		if active.stage == stageSwitched {
			active = nil
		}
	}
	checkConservation(t, seed, -1, dir, nodes, expected, touched)
}

// advanceMove takes the next legal step. Catch-up may repeat, and fencing may
// happen at any point after the copy, which is where interleavings matter.
func advanceMove(m *Move, rng *rand.Rand) error {
	switch m.stage {
	case stageNew:
		return m.Copy()
	case stageCopied, stageCaughtUp:
		if rng.Intn(2) == 0 {
			return m.CatchUp()
		}
		return m.Fence()
	case stageFenced:
		return m.Verify()
	case stageVerified:
		return m.Switch()
	}
	return nil
}

// checkConservation asserts that the current owner of every touched slot holds
// exactly the money the accepted writes add up to.
func checkConservation(t *testing.T, seed int64, step int, dir *Directory,
	nodes map[string]*Node, expected map[uint32]int64, touched map[uint32]bool) {
	t.Helper()
	for slot := range touched {
		owner := dir.Owner(slot)
		if got := nodes[owner].SlotTotal(slot); got != expected[slot] {
			t.Fatalf("seed %d step %d: slot %d owned by %s holds %d, accepted writes sum to %d",
				seed, step, slot, owner, got, expected[slot])
		}
	}
}
```

## How the Code Maps to the Guarantees

**Fixed slots bound the work.** `SlotOf` is a pure function of the account, so an account's location changes only when its slot is reassigned. A rebalance moves one slot's entries, not the key space. Changing the number of nodes never remaps most accounts, which a modulo placement would do.

**Epochs make stale routing visible.** `Directory.Reassign` increments the epoch on every ownership change, and requests carry the router's epoch. A router holding an old view gets `ErrWrongOwner` from the former owner or `ErrStaleView` from a node whose ownership is newer than the request. Both trigger a refresh. The router never guesses the owner.

**Acceptance checks run in a fixed order.** `Node.Accept` checks ownership, then fencing, then view freshness, then idempotency. Ownership and fencing refuse writes that would land on the wrong node or after the handoff began. The idempotency check makes retries safe, and because keys travel with entries, a retry after the move still finds its record on the new owner. The fenced refusal is deliberately not redirected: retrying against a fenced owner cannot succeed, so the caller must back off.

**The move's stages are enforced.** `Move` checks its stage before each step. `Copy` clears the destination first, so state from an earlier ownership cannot survive. `CatchUp` uses the destination's cursor, so repeated catch-up is harmless. `Import` also skips any key already recorded, so re-delivery cannot double-apply money. `Fence` stops writes on the source and imports the remainder, so the destination holds every entry up to a fixed position. `Verify` checks the totals and confirms nothing was accepted after the fence. `Switch` makes the destination an owner before the directory names it, so a request routed by the new directory always finds an owner.

**Scatter-gather never hides gaps.** `MerchantTotal` reads each account from its current owner. An unreachable owner goes into `Missing`, so a partial sum is labeled and cannot be mistaken for a complete one. This is the harvest trade-off in code form: a degraded answer is allowed, but it must say so.

**Hot keys are split, and the split has a cost.** `SubAccount` spreads a merchant's writes across slots. The gain is write throughput. The cost is that no single node sees the whole balance, so an overdraft floor cannot be enforced locally. The code leaves that check out on purpose and says so in the comment.

**The tests check the invariant, not the path.** The deterministic test covers each refusal, the redirect count, the retry after the move, and the labeled partial total. The randomized test runs 200 seeds of interleaved writes from two routers with stale views, moves to random destinations, random choices between catch-up and fence, and refreshes. After every step, the owner of each touched slot must hold the sum of accepted writes, tracked in an independent `expected` map. A silent loss, duplication, or stale-owner write breaks that equality, and the failure message names the seed, step, and slot.

## Limits

The model has no network and no failures. A node cannot crash in the middle of a move, and there is no abort path that unfences a source and clears a destination. There are no concurrent moves on one slot, and no cross-node transaction: a write touches exactly one slot, so there is no atomic debit-and-credit across Kestrel accounts. The overdraft floor for split sub-ledgers is not enforced. The copy groups behind each owner, with their own acknowledgment and failover rules, are also out of scope here.

## Mutations That Should Fail

Mutations show whether the tests carry weight. Each one should produce a failure that names a slot and a seed.

- Drop one entry in `Import` (for example, skip the first entry of each batch). Conservation fails on the first move that copies that slot.
- Remove the fence check in `Accept`. The source accepts writes after the fence, and both `Verify`'s tail check and the conservation check catch it.
- Remove `ClearSlot` from `Copy`. A node that held the slot earlier keeps stale balances, and a later move back breaks the totals.
- Remove the key check from `Import`. A re-delivered entry double-applies, and conservation fails once catch-up repeats.

If a mutation survives the tests, the tests are not yet testing that property, and the next step is to add a case that targets it.

Key takeaway: The sharded ledger is safe because fixed slots bound what a rebalance can touch, epoch-stamped requests make stale routing visible, the move's stages are enforced rather than assumed, and a conservation check against an independent record of accepted writes confirms after every step that no slot has lost or duplicated money, so the design is judged by the totals it preserves rather than by the moves that merely finish.

# Core Concepts in Leader Election

Leader election looks simple: a group picks a holder, and the holder acts until it fails. Each part of that sentence hides a failure mode, and the five concepts below are the ones a senior engineer needs in order to reason about any election design. Kestrel, the payments ledger on five nodes across three regions, provides the running examples. The settlement batch, which must run once per day, is the primary role. The Go sketches are illustrative, not compiled or run in this session.

## 1. Election, Leases, and Fencing Are Three Different Jobs

Election chooses a holder. A lease bounds how long that choice lasts. Fencing lets the protected resource reject a holder whose authority has lapsed. Teams often build one of these and assume the others are included. Each one alone fails in a specific way.

Election without a lease gives a holder authority that never expires. If the holder is partitioned from the group, the group elects a successor, and the old holder keeps acting because nothing told it to stop. Kestrel's settlement batch would then run on two nodes.

A lease without fencing bounds the holder's authority on paper, but the resource has no way to enforce the bound. A holder that pauses past its lease expiry and resumes will send its payouts, and the gateway accepts them because they look like any other request.

Fencing without election has no holder to fence against. The resource would see tokens from multiple claimants with nothing to say which one is legitimate.

The design question is therefore not "which election algorithm" but "which component decides who holds the role, which component limits how long they hold it, and which component refuses requests from anyone who no longer does." For Kestrel, the grantor decides, the lease limits, and the payouts gateway refuses.

## 2. The Lease Bounds Authority, and the Holder Must Leave Margin

A lease is a promise that no other node will hold the role before a given time. The grantor makes that promise based on its own clock. The holder must act within the promise, but it cannot read the grantor's clock, so it has to infer the expiry from its own.

The conservative rule is that the holder computes its expiry from the time it *sent* the acquire request, not the time the response arrived. The grantor's lease starts no earlier than the request reached it, so the holder's expiry is always at or before the grantor's. The holder then stops acting a margin before that expiry, to allow for clock drift and for the time its own last action takes to complete.

```go
// lease.go (holder side)
package election

import "time"

// Holder computes expiry from when the request was sent, which is never later
// than the grantor's start time. It stops acting a margin before expiry.
type Holder struct {
	Token  uint64
	expiry time.Time
	margin time.Duration
}

func (h *Holder) Acquired(token uint64, sentAt time.Time, ttl time.Duration) {
	h.Token = token
	h.expiry = sentAt.Add(ttl)
}

func (h *Holder) Valid(now time.Time) bool {
	return h.Token != 0 && now.Add(h.margin).Before(h.expiry)
}
```

Go's `time.Now` carries a monotonic reading, which makes `Before` and `After` immune to wall-clock jumps on the same machine. That protects the holder's local comparison. It does not protect the comparison across nodes, because the grantor's clock is a different machine's clock, which is why the design relies on tokens rather than on synchronized times.

For Kestrel, a ten-second lease with a two-second margin means the settlement batch stops starting new payouts at eight seconds after its send time. The margin is the price paid for clock drift and for the time the current payout call takes to return.

## 3. Fencing Tokens Make the Resource the Arbiter

A fencing token is a number that increases with every grant of the role. The resource records the highest token it has accepted and refuses anything lower. This moves the final decision from the holder, which may be stale, to the resource, which is current.

```go
// gateway.go
package election

import "errors"

var ErrStaleToken = errors.New("token older than the last accepted token")

// Gateway accepts a batch only if its token is at least the highest seen. The
// check and the update must be atomic with the write it guards; otherwise a
// stale holder can pass the check and then apply after a newer holder has.
type Gateway struct {
	maxToken uint64
}

func (g *Gateway) Submit(token uint64, batch string) error {
	if token < g.maxToken {
		return ErrStaleToken
	}
	g.maxToken = token
	// apply the batch here, within the same critical section
	return nil
}
```

Two details matter in practice. First, the token must come from the grantor's consensus-backed state, typically a log index or a counter that is durable across grantor failover. A token that resets after a grantor restart lets an old holder's token outrank a new one. Second, the check and the write must be atomic. If the gateway checks the token, releases its lock, and then applies the batch, a stale holder can pass the check and write after a newer holder has already written, and the check gives false assurance.

For Kestrel, each settlement batch carries the token under which it was produced. The gateway applies batches in token order and rejects anything older than its highest accepted token. A pausing holder cannot produce a duplicate payout after its successor has begun, because the gateway has already moved past its token.

## 4. A Holder Cannot Police Its Own Pauses

The most important failure in leader election is the stale holder that does not know it is stale. A garbage collection pause, a virtual machine stall, or a blocked thread can freeze a node for longer than its lease. When the node resumes, its code continues from where it stopped, and the `Valid` check it runs may execute before its next action, not after it. The check is not atomic with the action.

This is why the margin in concept 2 does not solve the problem. A margin shrinks the window in which a pause can cause harm, but any pause longer than the margin can still produce a stale action. The check at the holder is a best-effort guard. The real defense is the resource's token check in concept 3, which does not depend on the holder's view of time at all.

A useful test is to inject pauses at random points: in the middle of a batch, between the validity check and the submit, and after the submit returns. The test should assert that the gateway's outcome is the same as if the stale holder had never resumed. If the test fails when the pause falls between the check and the submit, the design relies on the holder's check and needs the gateway guard.

For Kestrel, the failure story is a settlement batch that stalls for fifteen seconds during a regional network event. The successor takes over with a higher token and runs the batch. The original resumes, passes its own `Valid` check because its local view of time was taken before the stall, and submits. The gateway rejects it. Without the gateway check, merchants would have been paid twice.

## 5. Quorum Decides, and Timeouts Trade Latency for False Failovers

The grantor must be a group, not a single node, because a single grantor is itself a point of failure and a source of split brain. Kestrel's grantor runs on the five-node consensus group. A lease is granted only with the agreement of a majority, which means a minority region cannot grant a lease to itself. If C1 is cut off, the majority on A and B continues to grant leases, and C1's view of the role is that it has no authority.

Majority-based grants give the safety property: at most one lease is valid at a time, because two majorities always intersect. They also give the liveness property that matters for failover: a holder that is still reachable by a majority can renew, and a holder that is not reachable is replaced by a candidate that a majority can reach.

The trade-off is timeout tuning. A short election timeout detects failures quickly and produces false failovers when a healthy holder is slow to renew, for example across regions with occasional latency spikes. A long timeout avoids false failovers but extends the time the role is unheld after a real failure. For Kestrel's cross-region layout, the renewal interval should exceed the typical cross-region round trip by a wide margin, and the lease duration should exceed several renewal intervals. Tuning should be measured against the observed latency distribution, including its tail, rather than against the median.

## How the Concepts Fit Together

The five concepts form one chain. The quorum (5) decides who holds the role. The lease (2) bounds that decision in time. The holder (2 and 4) acts within the bound, but cannot be trusted to remain within it. The token (3) carries the decision to the resource, which refuses anything the quorum has superseded. The timeout (5) decides how quickly the chain recovers from a holder that disappears.

Key takeaway: A leader election design is correct only when the resource itself refuses stale holders, because a holder can pause, disagree about time, or be partitioned while believing it still holds the role, so Kestrel's safety rests on quorum-granted leases that limit authority, fencing tokens that the payouts gateway checks atomically with each write, and timeouts measured against real cross-region latency.

# Worked Example: A Settlement Batch Survives a Pause

This example follows Kestrel's daily settlement batch through a takeover. The batch pays merchants from a payout list, and it must never pay the same payout twice. A1 holds the lease, pauses for about eighteen seconds in the middle of its work, and B1 takes over. When A1 resumes, it tries to finish the batch it started. The sequence shows each concept from the previous section operating together: the grantor's quorum-backed decisions, the holder's margin, the fencing token, and the gateway's atomic check. The Go code below is a deterministic simulation with a manual clock. I have not compiled or run it in this session.

## Setup

The lease grantor runs on the five-node consensus group, with nodes A1, A2, B1, B2, and C1. A grant needs acknowledgment from a majority, and this example assumes the grant completes. The lease has a ten-second TTL. The holder keeps a two-second margin, meaning it stops starting new payouts when less than two seconds remain before its expiry. The payouts gateway records the highest token it has accepted and records every payout it applies.

The batch contains ten payouts, P1 through P10. Each has a fixed amount, and the total is known in advance, so the final state can be checked against an independent number.

## The Timeline

| Time (s) | Event | Grantor state | Gateway state |
|---|---|---|---|
| 0.0 | A1 acquires the lease | holder A1, token 1, expires 10.0 | max token 0, nothing paid |
| 3.0 | A1 renews, sent at 3.0 | expires 13.0 | unchanged |
| 6.0 | A1 renews, sent at 6.0 | expires 16.0 | unchanged |
| 6.2 | A1 begins the batch. Its validity check at 6.2 passes, since 6.2 + 2.0 < 16.0 | unchanged | P1 to P4 applied under token 1 |
| 6.2 | A1 passes the check for P5 and then pauses (a garbage collection pause in production) | unchanged | P5 not yet submitted |
| 16.0 | A1's lease expires at the grantor. No renewal arrived, because A1 was paused | expired | unchanged |
| 16.5 | B1 acquires the lease | holder B1, token 2, expires 26.5 | max token 2 after B1's first submit |
| 16.5 | B1 reads the gateway's record, skips P1 to P4, and pays P5 to P10 under token 2 | holder B1 | P5 to P10 applied under token 2 |
| 24.0 | A1 resumes and submits P5 under token 1 | holder B1 | P5 submit rejected: token 1 is below max token 2 |
| 24.0 | A1 tries to renew | holder B1 | n/a. Renewal refused: A1 is not the holder |

At the end, every payout appears exactly once, and the total equals the batch total. A1's stale submit was refused at the gateway, not caught by A1's own check.

## The Code

The package models the grantor, the holder, the gateway, and the batch runner. The scenario reproduces the timeline above, and the control runs the same timeline with token enforcement turned off.

```go
// election.go
package election

import "errors"

var (
	ErrStaleToken = errors.New("token older than highest accepted")
	ErrNotHolder  = errors.New("node does not hold a valid lease")
)

// Grantor grants one lease at a time. Tokens increase with every new holder.
// The model assumes this state is quorum-committed; the consensus section
// covers how that is achieved.
type Grantor struct {
	holder  string
	token   uint64
	expires int64
}

// Acquire grants the lease if it is free or expired at now. The current holder
// acquiring again keeps its token.
func (g *Grantor) Acquire(node string, now, ttl int64) (uint64, bool) {
	if g.holder != "" && g.holder != node && now < g.expires {
		return 0, false
	}
	if g.holder != node || now >= g.expires {
		g.token++
	}
	g.holder = node
	g.expires = now + ttl
	return g.token, true
}

// Renew extends the lease only for the current holder with its current token.
func (g *Grantor) Renew(node string, token uint64, now, ttl int64) bool {
	if g.holder != node || g.token != token || now >= g.expires {
		return false
	}
	g.expires = now + ttl
	return true
}

// Holder computes its expiry from the time a request was sent, which is never
// later than the grantor's. It stops acting a margin before that expiry.
type Holder struct {
	Node   string
	Token  uint64
	expiry int64
	margin int64
}

func (h *Holder) Adopt(token uint64, sentAt, ttl int64) {
	h.Token = token
	h.expiry = sentAt + ttl
}

func (h *Holder) Valid(now int64) bool {
	return h.Token != 0 && now+h.margin < h.expiry
}

// Gateway applies payouts. With enforcement on, the token check and the write
// happen in one step, so no other submit can interleave between them.
type Gateway struct {
	enforceTokens bool
	maxToken      uint64
	paid          map[string]int
	total         int64
}

func NewGateway(enforceTokens bool) *Gateway {
	return &Gateway{enforceTokens: enforceTokens, paid: map[string]int{}}
}

func (g *Gateway) Submit(token uint64, payoutID string, amount int64) error {
	if g.enforceTokens {
		if token < g.maxToken {
			return ErrStaleToken
		}
		g.maxToken = token
	}
	g.paid[payoutID]++
	g.total += amount
	return nil
}

func (g *Gateway) Applied(payoutID string) bool { return g.paid[payoutID] > 0 }
func (g *Gateway) Paid(payoutID string) int     { return g.paid[payoutID] }
func (g *Gateway) Total() int64                 { return g.total }

type Batch struct {
	IDs     []string
	Amounts map[string]int64
}

// Run pays each payout the gateway has not recorded. Its record of applied
// payouts is the checkpoint a successor resumes from. The holder must be valid
// immediately before each submit. beforeSubmit lets a test pause a holder at the
// exact point between its check and its write.
func Run(h *Holder, gw *Gateway, b Batch, now func() int64, beforeSubmit func(string)) error {
	for _, id := range b.IDs {
		if gw.Applied(id) {
			continue
		}
		if !h.Valid(now()) {
			return ErrNotHolder
		}
		if beforeSubmit != nil {
			beforeSubmit(id)
		}
		if err := gw.Submit(h.Token, id, b.Amounts[id]); err != nil {
			return err
		}
	}
	return nil
}
```

```go
// election_test.go
package election

import (
	"errors"
	"fmt"
	"testing"
)

const ttl = 10000 // ten seconds, in milliseconds

func must(t *testing.T, ok bool, msg string) {
	t.Helper()
	if !ok {
		t.Fatal(msg)
	}
}

func settlementBatch() (Batch, int64) {
	b := Batch{Amounts: map[string]int64{}}
	var sum int64
	for i := 1; i <= 10; i++ {
		id := fmt.Sprintf("P%d", i)
		amt := int64(1000 + i)
		b.IDs = append(b.IDs, id)
		b.Amounts[id] = amt
		sum += amt
	}
	return b, sum
}

// runPausedHolderScenario drives the timeline from the worked example. It
// returns the gateway and the error A1 received when it resumed.
func runPausedHolderScenario(t *testing.T, enforce bool) (*Gateway, error) {
	t.Helper()
	var clock int64
	now := func() int64 { return clock }
	batch, _ := settlementBatch()
	g := &Grantor{}
	gw := NewGateway(enforce)
	a1 := &Holder{Node: "A1", margin: 2000}
	b1 := &Holder{Node: "B1", margin: 2000}

	// t=0 to 6: A1 acquires the lease and renews at 3s and 6s.
	tok, ok := g.Acquire("A1", 0, ttl)
	must(t, ok, "A1 acquire failed")
	a1.Adopt(tok, 0, ttl)
	for _, at := range []int64{3000, 6000} {
		clock = at
		must(t, g.Renew("A1", tok, at, ttl), "A1 renew failed")
		a1.Adopt(tok, at, ttl)
	}

	// t=6.2: A1 pays P1 to P4. Before P5 is submitted, it pauses. During the
	// pause, B1 takes over and finishes the batch, and then A1 resumes.
	clock = 6200
	var b1Err error
	pause := func(id string) {
		if id != "P5" {
			return
		}
		clock = 16500 // A1's lease expired at 16.0 with no renewal
		btok, ok := g.Acquire("B1", clock, ttl)
		if !ok {
			b1Err = errors.New("B1 acquire refused")
			return
		}
		b1.Adopt(btok, clock, ttl)
		if err := Run(b1, gw, batch, now, nil); err != nil {
			b1Err = err
		}
		clock = 24000 // A1 resumes
	}
	a1Err := Run(a1, gw, batch, now, pause)
	if b1Err != nil {
		t.Fatalf("B1 takeover: %v", b1Err)
	}
	if g.Renew("A1", tok, clock, ttl) {
		t.Fatal("A1 renewed after takeover")
	}
	return gw, a1Err
}

func TestPausedHolderIsRefusedAndPaysOnce(t *testing.T) {
	gw, a1Err := runPausedHolderScenario(t, true)
	if !errors.Is(a1Err, ErrStaleToken) {
		t.Fatalf("A1 error = %v, want ErrStaleToken", a1Err)
	}
	batch, want := settlementBatch()
	for _, id := range batch.IDs {
		if n := gw.Paid(id); n != 1 {
			t.Fatalf("%s paid %d times", id, n)
		}
	}
	if gw.Total() != want {
		t.Fatalf("total %d, want %d", gw.Total(), want)
	}
}

// The control runs the same timeline with token enforcement off. A1's submit
// for P5 is applied, so P5 is paid twice. A1's Applied check skips P6 to P10,
// because B1 has already recorded them.
func TestWithoutTokenCheckPaidHolderDuplicates(t *testing.T) {
	gw, a1Err := runPausedHolderScenario(t, false)
	if a1Err != nil {
		t.Fatalf("control A1 error = %v, want nil", a1Err)
	}
	batch, want := settlementBatch()
	if n := gw.Paid("P5"); n != 2 {
		t.Fatalf("P5 paid %d times, want 2", n)
	}
	if gw.Total() != want+batch.Amounts["P5"] {
		t.Fatalf("total %d, want %d", gw.Total(), want+batch.Amounts["P5"])
	}
}
```

## Reading the Example Against the Concepts

**The grantor decides, and the decision is recorded.** A1's lease ran from 0 to 16.0. B1 acquired the role only after that expiry, and the grantor incremented the token to 2. In production, the grant and the token would be quorum-committed on the five-node group, so a grantor failover could not hand out token 2 twice or reset the counter to 1. The code's `Grantor` stands in for that committed state.

**The lease bounds authority, and the margin leaves room for error.** A1 computed its expiry from the time it sent each renewal, so its view was never later than the grantor's. At 6.2 its check passed with more than two seconds remaining. The margin does not protect A1 from the pause, which began after its check. It only narrows the window in which a check can pass while the lease is about to end.

**The token protects the resource.** When A1 resumed at 24.0, its local view still said it held the role. Its `Valid` check would have failed at that point, but the check was already behind it. The gateway's refusal is the only defense that works, because it does not depend on A1's view of time. Without it, the control test shows the outcome: P5 is paid twice.

**The checkpoint is the gateway's record.** B1 did not need to know where A1 had stopped. It skipped every payout the gateway had already applied, which is how a successor resumes without a separate handoff. Payouts that were in flight when the pause began are handled by the same record, so a successor never needs to recover A1's position.

**Renewal refusal is a signal, not a guarantee.** When A1 tried to renew at 24.0, the grantor refused, and A1 learned that it had lost the role. That is useful for stopping work early, but the batch had already submitted P5 before learning it. The gateway check is what made that submit harmless.

## What the Example Leaves Out

The code is a single-process simulation with an exact clock. It does not model clock skew between grantor and holder, which the margin is meant to absorb. It does not model a grantor failover in the middle of the grant. It does not model partial network delivery of renewals, which is the cause of most false failovers, as the failure stories in the previous section showed. A production version needs randomized tests that vary the pause point, the clock offset, and the renewal delivery, with the invariant that every payout is paid exactly once and the total matches.

Key takeaway: In this timeline, the settlement batch was safe because the payouts gateway refused A1's stale submit atomically with the write, not because A1 checked its lease in time, so a Kestrel election design is correct only when the resource enforces the token and the successor can resume from the resource's own record of what was paid.

# Leader Election with Leases and Fencing Tokens

This example implements leader election the way the Kestrel design describes it: a coordination service grants a time-limited lease, the holder renews it while healthy, and a monotonically increasing token lets protected resources reject a deposed leader. It is a self-contained Go package with a deterministic test suite. I have not compiled or run it in this session.

## Layout

```
leader/
  store.go       coordination service: lease grant, renew, release
  node.go        election state machine run by each candidate
  resource.go    protected resource that enforces fencing tokens
  election_test.go
```

## store.go

```go
package leader

import (
	"errors"
	"sync"
	"time"
)

var (
	ErrHeld     = errors.New("lease held by another node")
	ErrNotOwner = errors.New("caller does not own the lease")
)

// Clock abstracts time so tests can drive it deterministically.
type Clock interface {
	Now() time.Time
}

// SystemClock uses the wall clock.
type SystemClock struct{}

func (SystemClock) Now() time.Time { return time.Now() }

// Lease is the record the coordination service holds for the current leader.
type Lease struct {
	Owner   string
	Token   uint64
	Expires time.Time
}

// Store is an in-memory stand-in for a consensus-backed coordination service
// such as etcd, ZooKeeper, or Consul. Its essential property is that every
// operation is an atomic compare-and-set on the lease record. A production store
// gets that property from a replicated log, not from a mutex.
type Store struct {
	mu    sync.Mutex
	clock Clock
	lease Lease
	seq   uint64
}

func NewStore(c Clock) *Store { return &Store{clock: c} }

// Acquire grants the lease to node if it is free or expired. Each grant
// increments the token, so tokens are totally ordered across the cluster.
func (s *Store) Acquire(node string, ttl time.Duration) (Lease, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.clock.Now()
	if s.lease.Owner != "" && now.Before(s.lease.Expires) {
		return Lease{}, ErrHeld
	}
	s.seq++
	s.lease = Lease{Owner: node, Token: s.seq, Expires: now.Add(ttl)}
	return s.lease, nil
}

// Renew extends the lease for its current owner. The token must match, so a
// node that lost the lease cannot renew it back. An expired lease cannot be
// renewed either; the holder must acquire again.
func (s *Store) Renew(node string, token uint64, ttl time.Duration) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.clock.Now()
	if s.lease.Owner != node || s.lease.Token != token || !now.Before(s.lease.Expires) {
		return ErrNotOwner
	}
	s.lease.Expires = now.Add(ttl)
	return nil
}

// Release gives up the lease immediately, so a successor need not wait for
// expiry. It fails harmlessly if the caller no longer owns the lease.
func (s *Store) Release(node string, token uint64) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.lease.Owner != node || s.lease.Token != token {
		return ErrNotOwner
	}
	s.lease = Lease{}
	return nil
}

// Current returns the lease record for observers and tests.
func (s *Store) Current() Lease {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.lease
}
