package leader

import (
	"errors"
	"sync"
)

var ErrStale = errors.New("stale fencing token")

// Resource is the protected object. It accepts a write only if the write's token
// is at least the highest token it has accepted. A deposed leader is refused
// even if it still believes it is leader, because the check does not depend on
// the leader's view of time.
type Resource struct {
	mu       sync.Mutex
	maxToken uint64
	entries  []string
}

func (r *Resource) Write(token uint64, entry string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if token < r.maxToken {
		return ErrStale
	}
	r.maxToken = token
	r.entries = append(r.entries, entry)
	return nil
}

func (r *Resource) Entries() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]string(nil), r.entries...)
}
