## node.go

```go
package leader

import (
	"context"
	"time"
)

// Node runs the election state machine. Each call to Tick performs at most one
// store operation. A node acts as leader only while its conservative local
// deadline (safeUntil) is in the future.
//
// A Node is not safe for concurrent use. Drive it from a single goroutine, and
// if other goroutines need to call IsLeader, guard it with a mutex or atomic.
type Node struct {
	ID     string
	store  *Store
	clock  Clock
	ttl    time.Duration
	margin time.Duration

	leader    bool
	token     uint64
	safeUntil time.Time // leader may act only before this instant

	OnElected func(token uint64)
	OnLost    func(reason string)
}

func NewNode(id string, s *Store, c Clock, ttl, margin time.Duration) *Node {
	return &Node{ID: id, store: s, clock: c, ttl: ttl, margin: margin}
}

// IsLeader reports whether this node may act as leader right now. It checks the
// local deadline, not just the flag, so a node paused past its deadline does not
// claim leadership while it is still stalled.
func (n *Node) IsLeader() bool {
	return n.leader && n.clock.Now().Before(n.safeUntil)
}

// Token returns the fencing token of the node's current leadership.
func (n *Node) Token() uint64 { return n.token }

// Tick advances the state machine once. Production code calls it from Run.
func (n *Node) Tick() {
	// Take the send time before the RPC. The store's grant time is never earlier,
	// so a deadline computed from sent is never later than the store's expiry.
	sent := n.clock.Now()
	if n.leader {
		n.renew(sent)
		return
	}
	lease, err := n.store.Acquire(n.ID, n.ttl)
	if err != nil {
		return
	}
	n.leader = true
	n.token = lease.Token
	n.safeUntil = sent.Add(n.ttl - n.margin)
	if n.OnElected != nil {
		n.OnElected(n.token)
	}
}

func (n *Node) renew(sent time.Time) {
	if err := n.store.Renew(n.ID, n.token, n.ttl); err != nil {
		n.stepDown("renewal refused: " + err.Error())
		return
	}
	n.safeUntil = sent.Add(n.ttl - n.margin)
}

// stepDown clears leadership and releases the lease so a successor can start
// without waiting for expiry. A failed release is harmless: the lease then
// expires on its own.
func (n *Node) stepDown(reason string) {
	n.leader = false
	_ = n.store.Release(n.ID, n.token)
	if n.OnLost != nil {
		n.OnLost(reason)
	}
}

// Run ticks the node at the given interval until ctx is done.
func (n *Node) Run(ctx context.Context, interval time.Duration) {
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			if n.leader {
				n.stepDown("shutdown")
			}
			return
		case <-t.C:
			n.Tick()
		}
	}
}
