package leader

import (
	"errors"
	"fmt"
	"math/rand"
	"testing"
	"time"
)

const (
	ttl    = 10 * time.Second
	margin = 2 * time.Second
)

// fakeClock is advanced explicitly by tests.
type fakeClock struct{ now time.Time }

func (f *fakeClock) Now() time.Time          { return f.now }
func (f *fakeClock) Advance(d time.Duration) { f.now = f.now.Add(d) }

func newCluster(c Clock, ids ...string) (*Store, []*Node) {
	s := NewStore(c)
	nodes := make([]*Node, 0, len(ids))
	for _, id := range ids {
		nodes = append(nodes, NewNode(id, s, c, ttl, margin))
	}
	return s, nodes
}

func leaders(nodes []*Node) []*Node {
	var out []*Node
	for _, n := range nodes {
		if n.IsLeader() {
			out = append(out, n)
		}
	}
	return out
}

func TestExactlyOneLeaderElected(t *testing.T) {
	clock := &fakeClock{now: time.Unix(1000, 0)}
	_, nodes := newCluster(clock, "A1", "A2", "B1")
	for _, n := range nodes {
		n.Tick()
	}
	got := leaders(nodes)
	if len(got) != 1 {
		t.Fatalf("leaders = %d, want 1", len(got))
	}
	if got[0].Token() != 1 {
		t.Fatalf("first token = %d, want 1", got[0].Token())
	}
}

// A leader that stops ticking must lose the role, and a survivor must take it
// with a larger token. The crashed node's own flag is still set, so this also
// checks that IsLeader consults the local deadline.
func TestFailoverAfterLeaderStops(t *testing.T) {
	clock := &fakeClock{now: time.Unix(1000, 0)}
	_, nodes := newCluster(clock, "A1", "A2", "B1")
	for _, n := range nodes {
		n.Tick()
	}
	crashed := nodes[0]
	survivors := nodes[1:]
	for i := 0; i < 20; i++ {
		clock.Advance(time.Second)
		for _, n := range survivors {
			n.Tick()
		}
	}
	if crashed.IsLeader() {
		t.Fatal("crashed node still claims leadership")
	}
	got := leaders(survivors)
	if len(got) != 1 {
		t.Fatalf("survivor leaders = %d, want 1", len(got))
	}
	if got[0].Token() != 2 {
		t.Fatalf("new token = %d, want 2", got[0].Token())
	}
}

// A leader paused past its lease passes its check before the pause and submits
// afterward. The fencing token must refuse that late write.
func TestPausedLeaderIsFencedOut(t *testing.T) {
	clock := &fakeClock{now: time.Unix(1000, 0)}
	_, nodes := newCluster(clock, "A1", "A2")
	res := &Resource{}
	a1, a2 := nodes[0], nodes[1]

	a1.Tick()
	if err := res.Write(a1.Token(), "A1-early"); err != nil {
		t.Fatalf("early write: %v", err)
	}

	clock.Advance(15 * time.Second) // A1 is paused longer than the TTL
	a2.Tick()
	if !a2.IsLeader() {
		t.Fatal("A2 did not take over")
	}
	if a1.IsLeader() {
		t.Fatal("paused A1 still claims leadership")
	}
	if err := res.Write(a2.Token(), "A2-current"); err != nil {
		t.Fatalf("A2 write: %v", err)
	}
	if err := res.Write(a1.Token(), "A1-late"); !errors.Is(err, ErrStale) {
		t.Fatalf("late A1 write error = %v, want ErrStale", err)
	}
	want := []string{"A1-early", "A2-current"}
	got := res.Entries()
	if len(got) != len(want) || got[0] != want[0] || got[1] != want[1] {
		t.Fatalf("entries = %v, want %v", got, want)
	}
}

// Randomized safety test. Nodes pause at random, which causes failovers and
// late resumptions. The invariants are:
//   - at no instant does more than one node act as leader;
//   - the lease token never decreases;
//   - every write by a node that acts as leader succeeds.
func TestSafetyUnderRandomPausesAndFailovers(t *testing.T) {
	for seed := int64(1); seed <= 200; seed++ {
		runRandomSchedule(t, seed)
	}
}

func runRandomSchedule(t *testing.T, seed int64) {
	t.Helper()
	rng := rand.New(rand.NewSource(seed))
	clock := &fakeClock{now: time.Unix(1000, 0)}
	s, nodes := newCluster(clock, "A1", "A2", "B1", "B2", "C1")
	res := &Resource{}
	pausedUntil := make(map[string]time.Time)
	var lastToken uint64
	var writes int

	for step := 0; step < 2000; step++ {
		clock.Advance(time.Duration(rng.Intn(400)) * time.Millisecond)

		for _, n := range nodes {
			if clock.Now().Before(pausedUntil[n.ID]) {
				continue
			}
			if rng.Intn(300) == 0 {
				pausedUntil[n.ID] = clock.Now().Add(time.Duration(1+rng.Intn(20)) * time.Second)
				continue
			}
			n.Tick()
		}

		cur := s.Current()
		if cur.Token < lastToken {
			t.Fatalf("seed %d step %d: token went backward %d -> %d", seed, step, lastToken, cur.Token)
		}
		lastToken = cur.Token

		active := leaders(nodes)
		if len(active) > 1 {
			t.Fatalf("seed %d step %d: %d nodes act as leader", seed, step, len(active))
		}
		for _, n := range active {
			entry := fmt.Sprintf("%s@%d", n.ID, step)
			if err := res.Write(n.Token(), entry); err != nil {
				t.Fatalf("seed %d step %d: leader %s write failed: %v", seed, step, n.ID, err)
			}
			writes++
		}
	}
	if lastToken < 2 {
		t.Fatalf("seed %d: only token %d issued; schedule exercised no failover", seed, lastToken)
	}
	if writes == 0 {
		t.Fatalf("seed %d: no leader wrote anything", seed)
	}
}
```

## Explanation

**The problem being solved.** Two nodes must never both act as the leader, because both could pay out, write, or migrate the same data. A node cannot tell from its own state whether it is still the leader, since a garbage collection pause, a network partition, or a VM stall can freeze it at any point. So election needs an external authority, here the `Store`, and the design has to stay safe when the leader's view of time is wrong.

**The lease.** `Store.Acquire` grants the role for a fixed TTL. The leader must renew before expiry, and the store refuses a renewal after expiry. A crashed leader therefore loses the role on its own without any coordination, which is what gives the system liveness.

**Conservative local deadlines.** `Tick` takes the send time before the RPC and sets `safeUntil = sent + ttl - margin`. The store's expiry is measured from its own grant time, which is never earlier than the send time, so `safeUntil` always falls before the store's expiry. The margin adds a further buffer for clock drift and delayed responses. `IsLeader` checks this deadline rather than just a flag, so a node that was paused past its deadline stops claiming leadership even before it has a chance to notice.

**Fencing tokens.** Every change of owner increments the token. A deposed leader can still be running code that believes it leads, so the protected resource is the component that has to enforce safety. `Resource.Write` refuses any token below the highest it has accepted. The test `TestPausedLeaderIsFencedOut` shows the case the design exists for: A1 holds a stale belief and its write is refused without any check on A1's side.

**Release for fast handover.** When a leader sees a failed renewal, `stepDown` calls `Release`, which lets a successor take over immediately rather than waiting for the TTL. A failed release is safe because the lease then expires as usual.

**What the tests check.**
- `TestExactlyOneLeaderElected` checks the basic grant and the first token.
- `TestFailoverAfterLeaderStops` checks liveness: the survivor takes over after expiry, with a larger token.
- `TestPausedLeaderIsFencedOut` checks the fencing argument.
- `TestSafetyUnderRandomPausesAndFailovers` is the broadest check. It runs 200 seeded schedules with random pauses and skipped ticks, and checks at-most-one-leader, monotonic tokens, and that leader writes succeed. A seed that never fails over would make the test pass vacuously, so the test also requires that some seed reaches token 2 or higher.

**Assumptions and limits.**
- The safety argument assumes no clock skew between the store and the nodes. The fake clock is exact, so the randomized test cannot exercise skew. A production version should randomize per-node clock offsets within a bounded error and make the margin exceed that bound.
- The `Store` is a single in-memory mutex. A real deployment needs a replicated store, so that the token counter itself survives coordinator failure. The `Store` interface is the seam for that.
- `Node` is single-goroutine. Exposing `IsLeader` to request handlers needs an atomic or mutex around the leader state.
- This is a lease-based design. Raft and similar protocols elect leaders with term-numbered votes and heartbeats instead. The fencing-token idea carries over, because a Raft term serves the same purpose as the token here.

