## dtx_example.py

```python
"""
dtx_example.py: two-phase commit and a saga in one runnable file.

Run with: python dtx_example.py
Everything is in memory. The coordinator log is a list, standing in for a
durable file, and each service keeps an idempotency table of results.
"""

import copy


class Crash(Exception):
    """Simulated process crash at a chosen point."""


class BusinessError(Exception):
    """The service refused. Retrying will not change the answer."""


class TransientError(Exception):
    """Timeout or lost reply. The effect may or may not have happened."""


# ----------------------------------------------------------------- 2PC

class Participant:
    """A resource manager holding a balance, with prepared (held) amounts."""

    def __init__(self, name, balance):
        self.name = name
        self.balance = balance
        self.holds = {}       # txn -> amount, promised but not yet decided
        self.decided = {}     # txn -> "commit" | "abort"

    def available(self):
        return self.balance - sum(self.holds.values())

    def prepare(self, txn, amount):
        if txn in self.decided:
            return self.decided[txn] == "commit"
        if txn in self.holds:
            return True                      # repeated prepare, same answer
        if self.available() < amount:
            return False                     # vote no; nothing is held
        self.holds[txn] = amount             # vote yes: a durable promise
        return True

    def commit(self, txn):
        if self.decided.get(txn) == "commit":
            return                           # redelivery is harmless
        self.balance -= self.holds.pop(txn)
        self.decided[txn] = "commit"

    def abort(self, txn):
        self.holds.pop(txn, None)
        self.decided.setdefault(txn, "abort")


class Coordinator:
    """Logs every decision before acting on it. The log write is the commit point."""

    def __init__(self, log):
        self.log = log                       # shared list: survives coordinator instances

    def _record(self, txn, event, **fields):
        self.log.append({"txn": txn, "event": event, **fields})

    def run(self, txn, parts, crash_at=None):
        """parts: {name: (participant, amount)}"""
        self._record(txn, "begin", names=list(parts))
        votes = [p.prepare(txn, amt) for p, amt in parts.values()]
        if crash_at == "before_decision":
            raise Crash(txn)
        decision = "commit" if all(votes) else "abort"
        self._record(txn, "decision", value=decision)   # the commit point
        if crash_at == "after_decision":
            raise Crash(txn)
        self._deliver(txn, decision, parts)
        return decision

    def recover(self, registry):
        """registry: {name: participant}. Finishes every transaction the log knows about."""
        begun, decided = {}, {}
        for rec in self.log:
            if rec["event"] == "begin":
                begun[rec["txn"]] = rec["names"]
            elif rec["event"] == "decision":
                decided[rec["txn"]] = rec["value"]
        outcomes = {}
        for txn, names in begun.items():
            if txn not in decided:
                self._record(txn, "decision", value="abort")   # presumed abort, logged first
                decided[txn] = "abort"
            for name in names:
                action = (registry[name].commit if decided[txn] == "commit"
                          else registry[name].abort)
                action(txn)
            outcomes[txn] = decided[txn]
        return outcomes

    def _deliver(self, txn, decision, parts):
        for participant, _ in parts.values():
            if decision == "commit":
                participant.commit(txn)
            else:
                participant.abort(txn)


# ---------------------------------------------------------------- Saga

class Service:
    """Base class: each effect runs at most once per idempotency key."""

    def __init__(self):
        self.results = {}                    # key -> result of the first execution
        self.lose_next_response = False      # test hook: effect applied, reply lost

    def once(self, key, effect):
        if key not in self.results:
            self.results[key] = effect()
        if self.lose_next_response:
            self.lose_next_response = False
            raise TransientError("reply lost after effect")
        return self.results[key]


class Inventory(Service):
    def __init__(self, stock):
        super().__init__()
        self.stock = stock
        self.reserved = {}                   # order -> qty
        self.cancelled = set()               # tombstones for compensated orders

    def reserve(self, key, order, qty):
        def effect():
            if order in self.cancelled:
                raise BusinessError("order already compensated")
            if self.stock < qty:
                raise BusinessError("out of stock")
            self.stock -= qty
            self.reserved[order] = qty
            return qty
        return self.once(key, effect)

    def release(self, key, order):
        def effect():
            self.cancelled.add(order)        # tombstone blocks a late reserve
            self.stock += self.reserved.pop(order, 0)
        return self.once(key, effect)


class Payments(Service):
    def __init__(self, limit):
        super().__init__()
        self.limit = limit
        self.charges = {}                    # order -> amount
        self.cancelled = set()

    def charge(self, key, order, amount):
        def effect():
            if order in self.cancelled:
                raise BusinessError("order already compensated")
            if amount > self.limit:
                raise BusinessError("declined")
            self.charges[order] = amount
            return amount
        return self.once(key, effect)

    def refund(self, key, order):
        def effect():
            self.cancelled.add(order)
            self.charges.pop(order, None)
        return self.once(key, effect)


class Shipping(Service):
    def __init__(self):
        super().__init__()
        self.scheduled = set()
        self.refuse = False                  # test hook: business refusal

    def schedule(self, key, order):
        def effect():
            if self.refuse:
                raise BusinessError("no carrier capacity")
            self.scheduled.add(order)
        return self.once(key, effect)


class Notifier(Service):
    def __init__(self):
        super().__init__()
        self.sent = []
        self.outage = 0                      # test hook: next N calls time out

    def send(self, key, order):
        if self.outage > 0:
            self.outage -= 1
            raise TransientError("notifier unreachable")
        return self.once(key, lambda: self.sent.append(order))


# (name, service, forward method, compensation or None, kind)
STEPS = [
    ("reserve",  "inventory", "reserve",  "release", "compensable"),
    ("charge",   "payments",  "charge",   "refund",  "compensable"),
    ("schedule", "shipping",  "schedule", None,      "pivot"),
    ("notify",   "notifier",  "send",     None,      "retriable"),
]


def forward_args(name, order):
    if name == "reserve":
        return (order["qty"],)
    if name == "charge":
        return (order["amount"],)
    return ()


def build_services():
    return {
        "inventory": Inventory(stock=10),
        "payments": Payments(limit=500),
        "shipping": Shipping(),
        "notifier": Notifier(),
    }


class Orchestrator:
    def __init__(self, services, store, retries=3):
        self.services = services
        self.store = store                   # durable saga table, keyed by saga id
        self.retries = retries

    def start(self, saga_id, order, crash_after=None):
        self._save(saga_id, {"order": order, "next": 0, "status": "running"})
        return self.resume(saga_id, crash_after)

    def resume(self, saga_id, crash_after=None):
        state = copy.deepcopy(self.store[saga_id])   # recovery reads durable state only
        order = state["order"]
        while state["status"] == "running" and state["next"] < len(STEPS):
            name, service, method, _comp, kind = STEPS[state["next"]]
            try:
                self._call(saga_id, service, method, *forward_args(name, order))
            except BusinessError:
                state["status"] = "stuck" if kind == "retriable" else "compensating"
            except TransientError:
                if kind == "retriable":
                    self._save(saga_id, state)
                    return "retry_later"     # nothing changed; a sweeper resumes later
                state["status"] = "compensating"
            else:
                state["next"] += 1
                self._save(saga_id, state)
                if crash_after == name:
                    raise Crash(saga_id)
        if state["status"] == "running":
            state["status"] = "completed"
        if state["status"] == "compensating":
            state["status"] = self._compensate(saga_id, state)
        self._save(saga_id, state)
        return state["status"]

    def _compensate(self, saga_id, state):
        # Includes the failed step: a timeout may hide an applied effect.
        # Compensations are idempotent, so this is a no-op for a step that never ran.
        for _name, service, _m, comp, _kind in reversed(STEPS[: state["next"] + 1]):
            if comp is None:
                continue
            try:
                self._call(saga_id, service, comp)
            except TransientError:
                return "compensating"        # sweeper retries; keys make it safe
        return "compensated"

    def _save(self, saga_id, state):
        self.store[saga_id] = copy.deepcopy(state)

    def _call(self, saga_id, service, method, *args):
        key = f"{saga_id}:{method}"          # stable across retries and instances
        last = None
        for _ in range(self.retries):
            try:
                return getattr(self.services[service], method)(key, saga_id, *args)
            except TransientError as err:
                last = err
        raise last


# ----------------------------------------------------------------- demo

def demo_2pc():
    print("2PC")
    log = []                                 # stands in for a durable, fsynced file
    ledger = Participant("ledger", balance=500)
    stock = Participant("stock", balance=10)
    registry = {"ledger": ledger, "stock": stock}
    coord = Coordinator(log)

    # 1. Normal commit
    assert coord.run("T1", {"ledger": (ledger, 100), "stock": (stock, 2)}) == "commit"
    assert (ledger.balance, stock.balance) == (400, 8)

    # 2. A no vote aborts everyone, with no lasting effects
    assert coord.run("T2", {"ledger": (ledger, 1000), "stock": (stock, 1)}) == "abort"
    assert (ledger.balance, stock.balance) == (400, 8) and not stock.holds

    # 3. Crash after the decision: holds persist until recovery delivers commit
    try:
        coord.run("T3", {"ledger": (ledger, 100), "stock": (stock, 2)},
                  crash_at="after_decision")
    except Crash:
        pass
    assert ledger.available() == 300 and ledger.balance == 400
    assert Coordinator(log).recover(registry)["T3"] == "commit"
    assert (ledger.balance, stock.balance) == (300, 6)

    # 4. Crash before the decision: recovery presumes abort
    try:
        coord.run("T4", {"ledger": (ledger, 50), "stock": (stock, 1)},
                  crash_at="before_decision")
    except Crash:
        pass
    assert ledger.available() == 250
    assert Coordinator(log).recover(registry)["T4"] == "abort"
    assert (ledger.balance, stock.balance) == (300, 6)
    assert not ledger.holds and not stock.holds
    print("  all 2PC scenarios passed")


def demo_saga():
    print("Saga")
    svc = build_services()
    inv, pay = svc["inventory"], svc["payments"]
    shp, ntf = svc["shipping"], svc["notifier"]
    store = {}                               # durable saga table
    a = Orchestrator(svc, store)

    # 1. Happy path
    assert a.start("o1", {"id": "o1", "qty": 2, "amount": 120}) == "completed"
    assert inv.stock == 8 and pay.charges["o1"] == 120
    assert "o1" in shp.scheduled and ntf.sent == ["o1"]

    # 2. Pivot refuses: earlier steps are compensated in reverse
    shp.refuse = True
    assert a.start("o2", {"id": "o2", "qty": 1, "amount": 80}) == "compensated"
    shp.refuse = False
    assert inv.stock == 8 and "o2" not in pay.charges and "o2" not in shp.scheduled

    # 3. Reply lost after the reservation applied: the retry does not reserve twice
    inv.lose_next_response = True
    assert a.start("o3", {"id": "o3", "qty": 1, "amount": 40}) == "completed"
    assert inv.stock == 7

    # 4. Orchestrator crashes after charge; a new instance on the same store finishes
    try:
